(()=>{'use strict';
const C=window.BotinCore,$=id=>document.getElementById(id),KEY='botin-workbench-prototype-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sheet=e=>window.BotinSheets.render({...e,descriptionTables:e?.descriptionTables||find(e?.id)?.descriptionTables},C.entryText(e||{}));
const names={loot:'Loot',dice:'D100',encounters:'Encuentros',market:'Mercado',craft:'Crafteo',library:'Biblioteca',homebrew:'Homebrew',contexts:'Contexto',help:'Ayuda y respaldo'};
const diceInputs={d100:'',d4:'',rarity:'all',artifacts:false};
const families={armamento:'Armamento',instrumentos:'Instrumentos',arcanos:'Objetos arcanos',reliquias:'Reliquias',equipo:'Equipo',azar:'Familia al azar'};
let db=C.initial(),blocked=false,view='loot',query='',filter='all',page=0,merchantId='general',marketKind='item',activeId=null,latest=null,pendingPackage=null,pendingBackup=null,editing=null,drawer='',craftSelection='',craftMaker='',craftQty=1,craftExtras=0,craftBase='',makeBase=false,baseOwned=false,editorPurpose='create',savedMagicSpell=null,scrollLevel=0,craftSale=null,changeOverride=null,selectedShare=new Set(),toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw)db=C.validate(JSON.parse(raw));}catch(err){blocked=true;}
const all=()=>[...window.CATALOG_DATA,...db.entries];
const find=id=>all().find(e=>e.id===id);
const accessible=()=>all().filter(e=>C.visible(e,db.campaign));
const available=()=>C.effective(all(),db.campaign,db.disabled);
const merchants=()=>db.merchants.filter(m=>C.visible(m,db.campaign));
const maker=()=>db.merchants.find(m=>m.id===merchantId)||merchants()[0];
const pretty=price=>C.displayMoney(price,db);
const coinRegistry=()=>C.currencyList(db);
const displayCoins=coins=>pretty(C.coinValue(coins)/100);
const isHB=e=>e.id.startsWith('custom:')||e.scope?.length||e.parent;
const tag=e=>e.type==='monster'&&e.monster?`<span class="tag">VD ${esc(e.monster.cr)} · ${e.monster.xp} PX</span>`:e.magic||e.rarity==='Artefacto'?`<span class="tag r-${C.RKEYS[C.RARITIES.indexOf(e.rarity)]||'artefacto'}">${esc(e.rarity)}</span>`:'';
const hb=e=>isHB(e)?'<span class="tag hb">Homebrew</span>':'';
const options=(list,value)=>list.map(([key,label])=>`<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const input=(id,label,value,attrs='')=>`<label>${label}<input id="${id}" value="${esc(value??'')}" ${attrs}></label>`;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function save(){if(blocked){$('save-status').textContent='⚠';$('save-status').title='Datos previos protegidos: exportá lo trabajado antes de importar un respaldo válido.';return false;}try{localStorage.setItem(KEY,JSON.stringify(db));$('save-status').textContent='●';$('save-status').title='Guardado en este navegador';return true;}catch(err){$('save-status').textContent='⚠';$('save-status').title='No se pudo guardar';toast('No se pudo guardar. Exportá un respaldo antes de cerrar.');return false;}}
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function info(title,body){$('info-title').textContent=title;$('info-body').innerHTML=body;$('info').showModal();}
function shop(){const key=db.campaign+'|'+merchantId;return db.shops[key]||(db.shops[key]={mode:'manual',floor:0,stock:{},cart:[],discount:0});}
function saleItems(){return available().filter(e=>['item','service'].includes(e.type)&&(e.type==='service'||maker().id==='general'||maker().categories.includes(e.category)));}
const cartLines=()=>shop().cart.filter(l=>saleItems().some(e=>e.id===l.id));
const payable=()=>C.total(cartLines(),available(),shop().discount);
function matches(e){return(filter==='all'||filter==='own'&&isHB(e)||filter==='base'&&!isHB(e)||e.type===filter||e.category===filter)&&C.norm(e.name+' '+(e.english||'')+' '+e.description+' '+e.category).includes(C.norm(query));}
function pager(count){const pages=Math.max(1,Math.ceil(count/16));page=Math.min(page,pages-1);return `<div class="pagination"><button data-action="prev" ${page?'':'disabled'}>←</button><span>${count} entradas · ${page+1}/${pages}</span><button data-action="next" ${page>=pages-1?'disabled':''}>→</button></div>`;}
function navigate(next){if(next==='spells'||next==='rules'){filter=next==='spells'?'spell':'rule';next='library';}else filter='all';view=names[next]?next:'loot';query='';page=0;activeId=null;history.replaceState(null,'','#'+view);render();}
function render(){
 document.body.dataset.theme=db.theme;$('theme').value=db.theme;$('campaign').innerHTML=options(db.campaigns.map(c=>[c.id,c.name]),db.campaign);$('title').textContent=names[view];
 if(!merchants().some(m=>m.id===merchantId))merchantId=merchants()[0].id;
 document.querySelectorAll('[data-view]').forEach(b=>{b.removeAttribute('aria-current');if(b.dataset.view===view)b.setAttribute('aria-current','page');});
 try{({loot:renderLoot,dice:renderDice,encounters:renderEncounters,market:renderMarket,craft:renderCraft,library:renderLibrary,homebrew:renderLibrary,contexts:renderContexts,help:renderHelp}[view])();}catch(err){$('view').innerHTML=`<div class="notice">${esc(err.message)}</div>`;}
}
function originalHTML(e){const base=e.parent?find(e.parent):null;return base?`<button class="text-button source" data-action="view-base" data-id="${esc(base.id)}">Referencia de origen: ${esc(base.name)}</button>`:'';}
function entryBody(e,market=false){const enabled=!(db.disabled[db.campaign]||[]).includes(e.id);return `<div class="entry-body"><div class="description sheet">${sheet(e)}</div>${e.spell?`<p class="source">${Object.entries(e.spell).map(([k,v])=>esc(k)+': '+esc(v)).join(' · ')}</p>`:''}<p class="source">${esc(e.origin)} · ${esc(e.status||'')}</p>${e.metadata?`<p class="source">Autoría: ${esc(e.metadata.author||'Sin declarar')} · versión ${esc(e.metadata.version||'—')} · ${esc(e.metadata.license||'Condiciones sin declarar')}</p>`:''}${e.type==='item'||e.type==='service'?`<p>Precio: ${esc(pretty(e.price))}${e.unit?' / '+esc(e.unit):''}</p>`:''}${e.priceNote?`<p class="subtle">${esc(e.priceNote)}</p>`:''}${isHB(e)?`<div class="hb-note">Contenido propio ${e.replacement?'· modifica la referencia conservada':'· variante independiente'} · ${enabled?'activo':'desactivado en este contexto'}.</div>`:''}${originalHTML(e)}<div class="row" style="margin-top:10px"><button data-action="${e.id.startsWith('custom:')?'edit-entry':'clone-entry'}" data-id="${esc(e.id)}">${e.id.startsWith('custom:')?'Editar homebrew':'Crear homebrew'}</button>${e.type==='item'?`<button data-action="craft-entry" data-id="${esc(e.id)}">Fabricación</button>`:''}${market?`<button data-action="cart-add" data-id="${esc(e.id)}">＋ Compra</button>`:''}</div>${e.type==='item'&&e.id.startsWith('custom:')?`<label class="check"><input type="checkbox" data-loot-enable="${esc(e.id)}" ${e.loot?'checked':''}>Disponible en loot</label>`:''}</div>`;}
function listHTML(entries,market=false){const filtered=entries.filter(matches),pagination=pager(filtered.length);return filtered.slice(page*16,page*16+16).map(e=>`<details class="list-entry" data-entry="${esc(e.id)}" ${activeId===e.id?'open':''}><summary>${!market&&e.id.startsWith('custom:')?`<input class="export-check" type="checkbox" data-share="${esc(e.id)}" aria-label="Compartir ${esc(e.name)}" ${selectedShare.has(e.id)?'checked':''}>`:''}<strong class="entry-name">${esc(e.name)}</strong>${tag(e)}${hb(e)}${market?`<span class="price">${esc(pretty(e.price))}</span><button class="add" data-action="cart-add" data-id="${esc(e.id)}" aria-label="Agregar ${esc(e.name)}">＋</button>`:`<span class="tag type-tag">${esc(C.TYPES[e.type])}</span>`}</summary>${market&&e.type==='item'?`<div class="subtle" style="padding:0 12px 6px">${shop().mode==='manual'?'Disponibilidad: decide el DM':(shop().stock[e.id]||0)+' disponible(s)'}</div>`:''}${entryBody(e,market)}</details>`).join('')+(!filtered.length?'<div class="empty">Sin coincidencias. Podés crear la entrada que falta.</div>':'')+pagination;}
let encounterPreview=null,encounterLootSaved=false,monsterCR='all',monsterKind='all';
const crOptions=()=>Object.keys(window.ENCOUNTER_DATA.xpByCR).sort((a,b)=>C.crValue(a)-C.crValue(b)).map(cr=>[cr,'VD '+cr]);
const encounterLabels={none:'Sin enemigos',low:'Baja',moderate:'Moderada',high:'Alta',over:'Supera alta',incomplete:'Cálculo incompleto'};
function encounterState(){return db.encounters[db.campaign]||(db.encounters[db.campaign]=C.encounterDefaults());}
function encounterPool(){const s=encounterState();let monsters=available().filter(e=>e.type==='monster');if(s.pool!=='all'){const list=visibleLists().find(l=>l.id===s.pool),ids=new Set(list?.entryIds||[]);monsters=monsters.filter(e=>ids.has(e.id));}return monsters;}
function creatureOptions(entries){return [...new Set(entries.filter(e=>e.type==='monster').map(e=>e.monster?.creatureType).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')).map(t=>[t,t]);}
function monsterLibraryFilters(){return `<select id="monster-filter-cr" aria-label="Filtrar monstruos por VD">${options([['all','Todos los VD'],...crOptions()],monsterCR)}</select><select id="monster-filter-kind" aria-label="Tipo de monstruo">${options([['all','Todos los tipos de criatura'],...creatureOptions(accessible())],monsterKind)}</select>`;}
function encounterPicker(){const s=encounterState(),pool=encounterPool().filter(e=>(s.cr==='all'||e.monster.cr===s.cr)&&(s.creatureType==='all'||e.monster.creatureType===s.creatureType));return crOptions().map(([cr,label])=>{const entries=pool.filter(e=>e.monster.cr===cr).sort((a,b)=>a.name.localeCompare(b.name,'es'));return entries.length?`<optgroup label="${label}">${options(entries.map(e=>[e.id,e.name+' · '+e.monster.xp+' PX']),'')}</optgroup>`:'';}).join('');}
function renderEncounters(){const s=encounterState();$('view').innerHTML=`<div class="work-grid"><aside class="panel"><div class="panel-body"><div class="form-grid">${input('enc-level','Nivel de los PJ',s.level,'type="number" min="1" max="20" step="1" data-enc-setting="level"')}${input('enc-players','Jugadores / PJ',s.players,'type="number" min="1" max="20" step="1" data-enc-setting="players"')}</div><label>Dificultad objetivo<select id="enc-difficulty" data-enc-setting="difficulty">${options([['low','Baja'],['moderate','Moderada'],['high','Alta']],s.difficulty)}</select></label><button class="primary full" data-action="enc-generate">⚄ Generar encuentro</button><details class="fold" data-fold="enc-filters"><summary>Origen y filtros</summary><div class="field-stack"><label>Lista de criaturas<select id="enc-pool" data-enc-setting="pool">${options([['all','Bestiario habilitado'],...visibleLists().filter(l=>l.entryIds.some(id=>find(id)?.type==='monster')).map(l=>[l.id,l.name])],s.pool)}</select></label><label>VD<select id="enc-cr" data-enc-setting="cr">${options([['all','Todos los VD'],...crOptions()],s.cr)}</select></label><label>Tipo de criatura<select id="enc-kind" data-enc-setting="creatureType">${options([['all','Todos los tipos'],...creatureOptions(available())],s.creatureType)}</select></label>${input('enc-max','Máximo de criaturas',s.maxCreatures,'type="number" min="1" max="100" step="1" data-enc-setting="maxCreatures"')}<label class="check"><input type="checkbox" data-enc-setting="allowHigher" ${s.allowHigher?'checked':''}>Permitir VD superior al nivel en generación</label></div></details><details class="fold" data-fold="enc-manual"><summary>Añadir enemigos manualmente</summary><div class="field-stack"><label>Criatura<select id="enc-monster"><option value="">Elegir criatura…</option>${encounterPicker()}</select></label>${input('enc-add-qty','Cantidad',1,'type="number" min="1" max="100" step="1"')}<button data-action="enc-add">Agregar criatura</button><details class="fold"><summary>Calcular solo por VD</summary><label>VD manual<select id="enc-manual-cr">${options(crOptions(),'1')}</select></label><button data-action="enc-add-cr">Agregar por VD</button><p class="subtle">Consulta sin ficha de criatura. VD 0 usa 10 PX; una ficha puede indicar 0 PX. Para una criatura nueva, usá Crear homebrew → Monstruo.</p></details><button data-action="enc-new-monster">Crear monstruo homebrew</button></div></details><details class="fold"><summary>Regla de cálculo</summary><p class="subtle">SRD 5.2.1 · Combat Encounters. Presupuesto por nivel × cantidad de PJ. Se suman los PX de las criaturas, sin sumar sus VD ni aplicar multiplicadores de cantidad de 2014. Generación: hasta tres fichas distintas y el máximo elegido, sin superar el presupuesto. El presupuesto orienta la dificultad; revisá las capacidades y el terreno.</p></details></div></aside><section id="enc-output"></section></div>`;renderEncounterResult();}
function renderEncounterResult(){const s=encounterState(),a=C.assessEncounter(s,available()),target=a.budget[s.difficulty];$('enc-output').innerHTML=`<div class="panel panel-body"><div class="row spread"><h2>${encounterLabels[a.difficulty]}</h2><span>${a.count} criaturas · ${a.xp.toLocaleString('es-AR')} PX</span></div><p class="subtle">Objetivo ${encounterLabels[s.difficulty].toLowerCase()}: ${target.toLocaleString('es-AR')} PX · ${a.remaining>=0?'Quedan '+a.remaining.toLocaleString('es-AR')+' PX':'Exceso de '+(-a.remaining).toLocaleString('es-AR')+' PX'}</p><details class="fold" data-fold="enc-budget"><summary>Presupuestos de esta mesa</summary>${['low','moderate','high'].map(k=>`<div class="compact-line"><span>${encounterLabels[k]}</span><span>${a.budget[k].toLocaleString('es-AR')} PX</span></div>`).join('')}<p class="subtle">PX por PJ si se reparten por igual: ${a.share.toLocaleString('es-AR',{maximumFractionDigits:2})}. No registra progreso.</p></details>${a.warnings.length?`<details class="fold" data-fold="enc-warnings"><summary>Revisar · ${a.warnings.length} avisos</summary>${a.warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}</details>`:''}</div><div style="margin-top:12px">${a.rows.map(row=>`<details class="list-entry" data-entry="enc-${esc(row.id)}"><summary><strong class="entry-name">${row.qty} × ${esc(row.name)}</strong><span class="tag">VD ${esc(row.cr||'—')}</span><span>${row.missing?'—':(row.xp*row.qty).toLocaleString('es-AR')+' PX'}</span></summary><div class="entry-body"><div class="row"><label>Cantidad<input type="number" min="1" max="100" value="${row.qty}" data-enc-qty="${esc(row.id)}"></label>${row.entry?.monster.lairXp!=null?`<label class="check"><input type="checkbox" data-enc-lair="${esc(row.id)}" ${row.lair?'checked':''}>En guarida · ${row.entry.monster.lairXp} PX por criatura</label>`:''}<button data-action="enc-remove" data-id="${esc(row.id)}">Quitar</button></div>${row.entry?`<div class="description sheet">${sheet(row.entry)}</div><p class="source">${esc(row.entry.origin)}</p><button data-action="clone-entry" data-id="${esc(row.id)}">Crear homebrew</button>`:'<p class="subtle">Sin bloque de estadísticas asociado.</p>'}</div></details>`).join('')||'<div class="empty">Generá un encuentro o agregá criaturas por su VD.</div>'}</div><div class="row"><button data-action="enc-export" ${a.count?'':'disabled'}>↓ TXT</button><button data-action="enc-clear" ${a.count?'':'disabled'}>Vaciar encuentro</button></div><details class="fold" data-fold="enc-loot"><summary>Botín opcional${s.lootMode==='none'?' · sin botín':''}</summary><label>Recompensa elegida por el DM<select id="enc-loot" data-enc-setting="lootMode">${options([['none','Sin botín'],['personal','Pertenencias · por VD y cantidad'],['hoard','Tesoro acumulado · VD más alto']],s.lootMode)}</select></label><button data-action="enc-loot" ${!a.count||a.missing||s.lootMode==='none'?'disabled':''}>Generar botín</button><div id="enc-loot-result">${encounterPreview?encounterLootHTML(encounterPreview):'<p class="subtle">'+(s.lootMode==='none'?'Este encuentro no entrega botín.':'El botín se genera al pulsar el botón.')+'</p>'}</div></details>`;}
function encounterLootHTML(r){return `<div class="loot-content"><div class="compact-line"><span>Monedas</span><span>${esc(displayCoins(r.coins))}</span></div>${r.valuables.map(v=>`<div class="compact-line"><span>${esc(v.name)}</span><span>${esc(pretty(v.price))}</span></div>`).join('')}<div class="compact-line"><strong>Valor monetario</strong><strong>${esc(pretty(r.budget))}</strong></div>${r.items.map(e=>`<details class="list-entry"><summary><strong>${esc(e.name)}</strong>${tag(e)}${hb(e)}</summary><div class="description sheet">${sheet(e)}</div></details>`).join('')}${r.warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<button data-action="enc-save-loot" ${encounterLootSaved?'disabled':''}>${encounterLootSaved?'Guardado en Loot':'Guardar en Loot'}</button></div>`;}
function updateEncounter(change){const next=structuredClone(db),s=next.encounters[next.campaign]||C.encounterDefaults();change(s);next.encounters[next.campaign]=s;db=C.validate(next);encounterPreview=null;encounterLootSaved=false;save();}
function addEncounterRow(row){updateEncounter(s=>{const old=s.rows.find(r=>r.id===row.id);if(old)old.qty+=row.qty;else s.rows.push(row);});renderEncounterResult();}
function encounterText(){const s=encounterState(),a=C.assessEncounter(s,available());return [`Encuentro · ${s.players} PJ de nivel ${s.level}`,`Objetivo ${encounterLabels[s.difficulty]} · presupuesto ${a.budget[s.difficulty]} PX`,`Resultado ${encounterLabels[a.difficulty]} · ${a.xp} PX`,...a.rows.map(r=>`${r.qty} × ${r.name} · VD ${r.cr} · ${r.xp*r.qty} PX${r.lair?' · en guarida':''}`),...a.warnings,...(encounterPreview?['\nBotín',`Valor monetario ${pretty(encounterPreview.budget)}`,...encounterPreview.valuables.map(v=>v.name+' · '+pretty(v.price)),...encounterPreview.items.map(e=>e.name+'\n'+e.description)]:['Sin botín generado'])].join('\n');}
let libraryList='spells',libraryMode='browse',listDraft=null,listSource='spells',listSearch='',rightSelection=new Set(),leftSelection=new Set(),pendingListPackage=null;
const listDefs=()=>C.listDefinitions(window.TABLE_DATA).filter(d=>d.id!=='unclassified'||C.listEntries(accessible(),d.id,window.TABLE_DATA).length);
const visibleLists=()=>db.customLists.filter(l=>C.visible(l,db.campaign));
function sourceEntries(id){if(id.startsWith('saved:')){const ids=new Set(db.customLists.find(l=>l.id===id.slice(6))?.entryIds||[]);return accessible().filter(e=>ids.has(e.id));}return C.listEntries(accessible(),id,window.TABLE_DATA);}
function listOptions(selected){return [...new Set(listDefs().map(l=>l.section))].map(section=>`<optgroup label="${esc(section)}">${options(listDefs().filter(l=>l.section===section).map(l=>[l.id,l.name]),selected)}</optgroup>`).join('')+(visibleLists().length?`<optgroup label="Mis listas">${options(visibleLists().map(l=>['saved:'+l.id,l.name]),selected)}</optgroup>`:'');}
function listTabs(){return `<div class="tools-row"><button data-action="library-mode" data-mode="browse" class="${libraryMode==='browse'?'primary':''}">Listas</button><button data-action="library-mode" data-mode="custom" class="${libraryMode==='custom'?'primary':''}">Mis listas</button><button data-action="new-entry">Crear homebrew</button></div>`;}
function renderLibrary(){if(view==='library'){if(libraryList.startsWith('saved:')&&!visibleLists().some(l=>'saved:'+l.id===libraryList))libraryList='spells';
 $('view').innerHTML=listTabs()+`<div id="library-content"></div>`;
 if(libraryMode==='custom'){renderListBuilder();return;}
 $('library-content').innerHTML=`<div class="tools-row"><select id="library-list" aria-label="Lista de biblioteca">${listOptions(libraryList)}</select><input id="search" type="search" aria-label="Buscar contenido" placeholder="Buscar en esta lista…" value="${esc(query)}"><select id="filter" aria-label="Origen">${options([['all','Todo el contenido'],['base','Base'],['own','Homebrew']],filter)}</select></div>${libraryList==='type:monster'?'<div class="tools-row">'+monsterLibraryFilters()+'</div>':''}<div id="table-reference"></div><div id="results"></div>`;
 renderList();return;
 }
 $('view').innerHTML=`<div class="tools-row"><input id="search" type="search" aria-label="Buscar contenido" placeholder="Buscar nombre o descripción…" value="${esc(query)}"><select id="filter" aria-label="Tipo de contenido">${options([['all','Todos los tipos'],...Object.entries(C.TYPES)],filter)}</select><button data-action="new-entry">Crear homebrew</button><button data-action="import-content">Importar contenido</button><button data-action="export-content">Exportar selección</button></div><div id="results"></div>`;renderList();}
function renderTableReference(){const node=$('table-reference');if(!node)return;if(!libraryList.startsWith('table:')){node.innerHTML='';return;}const rows=window.TABLE_DATA.tables[libraryList.slice(6)]||[];node.innerHTML=`<details class="fold" data-fold="library-d100"><summary>Ver tabla D100 · ${rows.length} resultados</summary><div class="table-scroll"><table class="reference-table"><thead><tr><th>D100</th><th>Objeto</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.start===r.end?r.start:r.start+'–'+r.end}</td><td><button class="text-button" data-action="list-entry-info" data-id="${esc(r.itemId)}">${esc(find(r.itemId)?.name||r.name)}</button></td></tr>`).join('')}</tbody></table></div></details>`;}
function newListDraft(id){const saved=db.customLists.find(l=>l.id===id);listDraft=saved?structuredClone(saved):{id:'list:'+C.uid(),name:'',scope:[],entryIds:[]};rightSelection.clear();leftSelection.clear();listSearch='';}
function captureListDraft(){if(!listDraft)return;if($('custom-list-name'))listDraft.name=$('custom-list-name').value; if($('list-global'))listDraft.scope=getScope('list');}
function remainingSource(){const included=new Set(listDraft?.entryIds||[]);return sourceEntries(listSource).filter(e=>!included.has(e.id)&&C.norm(e.name+' '+(e.english||'')).includes(C.norm(listSearch))).sort((a,b)=>a.name.localeCompare(b.name,'es'));}
function selectionRow(id,side){const e=find(id),outside=e&&!C.visible(e,db.campaign);return `<div class="pick-row"><label><input type="checkbox" data-list-pick="${side}" value="${esc(id)}" ${(side==='right'?rightSelection:leftSelection).has(id)?'checked':''}><span>${esc(e?.name||'Referencia no instalada · '+id)} ${outside?'<small>· otro contexto</small>':''}</span>${e?tag(e)+hb(e):''}</label><button type="button" data-action="list-entry-info" data-id="${esc(id)}" aria-label="Ver ${esc(e?.name||id)}" ${e?'':'disabled'}>ⓘ</button></div>`;}
function renderTransferRows(resetRight=false){const leftTop=$('custom-left')?.scrollTop||0,rightTop=resetRight?0:$('custom-right')?.scrollTop||0,right=remainingSource();$('custom-left').innerHTML=listDraft.entryIds.map(id=>selectionRow(id,'left')).join('')||'<p class="empty">Elegí una lista a la derecha y agregá las fichas que quieras.</p>';$('custom-right').innerHTML=right.map(e=>selectionRow(e.id,'right')).join('')||'<p class="empty">Sin fichas para agregar con este filtro.</p>';$('custom-count').textContent=listDraft.entryIds.length+' fichas';$('source-count').textContent=right.length+' disponibles';$('custom-left').scrollTop=leftTop;$('custom-right').scrollTop=rightTop;updateTransferButtons();}
function updateTransferButtons(){if($('list-add'))$('list-add').disabled=!rightSelection.size;if($('list-remove'))$('list-remove').disabled=!leftSelection.size;}
function renderListBuilder(){const sourceScroll=$('list-sources')?.scrollTop||0;if(listSource.startsWith('saved:')&&!visibleLists().some(l=>'saved:'+l.id===listSource))listSource='spells';if(!listDraft)newListDraft(visibleLists()[0]?.id);const sections=[...new Set(listDefs().map(l=>l.section))];$('library-content').innerHTML=`<form id="custom-list-form"><div class="tools-row"><label>Mis listas<select id="custom-list-select"><option value="">Lista nueva</option>${options(visibleLists().map(l=>[l.id,l.name]),db.customLists.some(l=>l.id===listDraft.id)?listDraft.id:'')}</select></label><button type="button" data-action="list-new">Nueva lista</button><button type="button" data-action="list-import">Importar JSON</button></div><div class="tools-row list-form-title">${input('custom-list-name','Nombre de mi lista',listDraft.name,'required maxlength="180" placeholder="Mi lista…"')}<button class="primary" type="submit">Guardar lista</button><button type="button" data-action="list-export">Exportar JSON</button></div><details class="fold" data-fold="custom-list-scope"><summary>Disponibilidad</summary>${scopeFields(listDraft.scope,'list')}</details><div class="list-builder"><section class="transfer-panel"><h2>Mi lista <span id="custom-count"></span></h2><div id="custom-left" class="pick-scroll" aria-label="Contenido de mi lista"></div></section><section class="transfer-middle"><h2>Listas</h2><div class="transfer-sources" id="list-sources">${sections.map(section=>`<details class="fold" data-fold="source-${esc(section)}" ${section==='Objetos y equipo'||section==='Biblioteca'?'open':''}><summary>${esc(section)}</summary>${listDefs().filter(l=>l.section===section).map(l=>`<button type="button" data-action="list-source" data-id="${esc(l.id)}" ${listSource===l.id?'aria-current="true"':''}>${esc(l.name)}</button>`).join('')}</details>`).join('')}${visibleLists().length?`<details class="fold"><summary>Mis listas</summary>${visibleLists().map(l=>`<button type="button" data-action="list-source" data-id="saved:${esc(l.id)}">${esc(l.name)}</button>`).join('')}</details>`:''}</div><div class="transfer-arrows"><button type="button" id="list-add" data-action="list-add">← Agregar</button><button type="button" id="list-remove" data-action="list-remove">Quitar →</button></div></section><section class="transfer-panel"><h2>${esc(listDefs().find(l=>l.id===listSource)?.name||db.customLists.find(l=>'saved:'+l.id===listSource)?.name||'Contenido')} <span id="source-count"></span></h2><div class="tools-row"><input id="list-search" type="search" aria-label="Buscar en lista de origen" placeholder="Buscar…" value="${esc(listSearch)}"><button type="button" data-action="list-select-visible">Seleccionar visibles</button></div><div id="custom-right" class="pick-scroll" aria-label="Fichas disponibles para agregar"></div></section></div></form>`;renderTransferRows();$('list-sources').scrollTop=sourceScroll;}
function saveCustomList(){captureListDraft();const next=structuredClone(db),i=next.customLists.findIndex(l=>l.id===listDraft.id);i<0?next.customLists.push(structuredClone(listDraft)):next.customLists[i]=structuredClone(listDraft);db=C.validate(next);save();renderLibrary();toast('Lista guardada.');}
function listImportPreview(p){pendingListPackage=C.validateListPackage(p);info('Importar lista',`<p>${esc(p.list.name)} · ${p.list.entryIds.length} referencias · ${p.entries.length} fichas propias.</p><form id="list-import-form">${scopeFields([],'list-import')}<label>Contenido coincidente<select id="list-collision">${options([['skip','Usar la ficha existente'],['copy','Crear copias con IDs nuevos']],'skip')}</select></label><p class="subtle">Las fichas propias nuevas se importan desactivadas. La lista conserva sus referencias.</p><button class="primary">Importar lista</button></form>`);}
function renderList(){if(view==='market')$('results').innerHTML=listHTML(saleItems().filter(e=>e.type===marketKind),true);else if(view==='library'){renderTableReference();$('results').innerHTML=listHTML(sourceEntries(libraryList).filter(e=>libraryList!=='type:monster'||(monsterCR==='all'||e.monster?.cr===monsterCR)&&(monsterKind==='all'||e.monster?.creatureType===monsterKind)));}else $('results').innerHTML=listHTML(accessible().filter(e=>view!=='homebrew'||isHB(e)));}
function renderMarket(){const s=shop();$('view').innerHTML=`<div class="tools-row"><select id="merchant" aria-label="Comerciante">${options(merchants().map(m=>[m.id,m.name]),merchantId)}</select><button data-action="new-merchant">＋ Comerciante</button><button data-action="market-kind" data-kind="item" class="${marketKind==='item'?'primary':''}">Objetos</button><button data-action="market-kind" data-kind="service" class="${marketKind==='service'?'primary':''}">Servicios</button></div><div class="market-grid"><section><div class="tools-row"><input id="search" type="search" placeholder="Buscar…" aria-label="Buscar mercado" value="${esc(query)}"><select id="filter" aria-label="Categoría">${options([['all','Todas las categorías'],...[...new Set(saleItems().filter(e=>e.type===marketKind).map(e=>e.category))].map(c=>[c,c])],filter)}</select></div><details class="fold"><summary>Disponibilidad y comerciante</summary><div class="fold-content"><p class="subtle">${esc(maker().note)}</p><div class="form-grid"><label>Disponibilidad<select id="stock-mode">${options([['manual','Decide el DM'],['random','Stock aleatorio']],s.mode)}</select></label>${input('stock-floor','Stock mínimo por objeto',s.floor,'type="number" min="0" max="100"')}</div><button data-action="restock">Renovar stock</button><p class="subtle">Propuesta de stock: 8 objetos distintos con 1–3 unidades adicionales. Los servicios no se sortean ni consumen stock. Se conserva hasta renovarlo.</p></div></details><div id="results"></div></section><aside class="panel receipt-panel"><div id="cart"></div></aside></div>`;renderList();renderCart();}
function paymentFields(prefix,coins){const fields=list=>list.map(([key,label])=>input(prefix+'-'+key,label,coins[key]||0,'data-'+prefix+'="'+key+'" type="number" min="0" max="1000000000" step="1"')).join(''),extra=coinRegistry().filter(([key])=>!C.BASE_COINS.some(c=>c[0]===key));return fields(C.BASE_COINS)+(extra.length?`<details class="fold" style="grid-column:1/-1" data-fold="${prefix}-optional-coins"><summary>Monedas opcionales${extra.some(([key])=>coins[key])?' · hay monedas en uso':''}</summary><div class="payment-grid">${fields(extra)}</div></details>`:'');}
function currencySettings(){C.ensureCurrencies(db);const prefs=db.currencies[db.campaign],format=value=>C.currencyText(C.changeIn(value,C.BASE_COINS),C.BASE_COINS);info('Monedas · '+db.campaigns.find(c=>c.id===db.campaign).name,`<div class="field-stack"><p class="subtle">Base: oro, plata y cobre.</p><label class="check"><input type="checkbox" data-currency-official="platinum" ${prefs.platinum?'checked':''}>Habilitar platino</label><label class="check"><input type="checkbox" data-currency-official="electrum" ${prefs.electrum?'checked':''}>Habilitar electro</label>${prefs.custom.map(c=>`<label class="check"><input type="checkbox" data-currency-enable="${esc(c.key)}" ${c.enabled?'checked':''}>${esc(c.name)} · ${esc(format(c.value))}</label>`).join('')}<details class="fold"><summary>Agregar moneda propia</summary><form id="currency-form" class="field-stack">${input('currency-name','Nombre','','required maxlength="80"')}<div class="form-grid">${input('currency-value','Equivale a',1,'required type="number" min="0.01" max="10000000" step="0.01"')}<label>Unidad<select id="currency-unit">${options(C.BASE_COINS.map(([key,label])=>[key,label]),'po')}</select></label></div><label class="check"><input id="currency-enable-new" type="checkbox" checked>Habilitar en este contexto</label><button class="primary">Agregar moneda</button></form></details></div>`);}
function renderCart(){const lines=cartLines(),sum=payable(),s=shop();$('cart').innerHTML=`<details id="cart-fold" ${lines.length?'open':''}><summary class="panel-head">Compra · ${lines.length} entradas · ${esc(pretty(sum.amount))}${sum.pending?' + pendientes':''}</summary><div class="receipt">${lines.map(l=>{const e=find(l.id);return `<div class="cart-line"><div class="line-top"><strong>${esc(e.name)}</strong><span data-line-total="${esc(e.id)}">${esc(pretty(e.price==null?null:e.price*l.qty))}</span></div><div class="line-bottom"><label class="qty">${esc(e.unit||'Cantidad')} <input data-qty="${esc(e.id)}" type="number" min="1" max="10000" value="${l.qty}" aria-label="Cantidad de ${esc(e.name)}"></label><button data-action="cart-remove" data-id="${esc(e.id)}">Quitar</button></div>${e.type==='item'&&s.mode==='random'&&l.qty>(s.stock[e.id]||0)?'<p class="subtle">Supera el stock. El DM decide disponibilidad o fabricación.</p>':''}</div>`;}).join('')||'<p class="subtle">Agregá objetos o servicios con ＋.</p>'}<label>Descuento decidido por el DM (%)<input id="discount" type="number" min="0" max="100" step="1" value="${s.discount}"></label><div class="receipt-total"><span>${sum.pending?'Subtotal conocido':'Total'}</span><strong id="cart-total">${esc(pretty(sum.amount))}</strong></div>${sum.pending?'<p class="notice">Hay precios pendientes. Definilos en una variante antes de calcular un pago final.</p>':''}<details class="fold"><summary>Pago y vuelto</summary><div class="fold-content"><div class="payment-grid">${paymentFields('pay',s.payment||{})}</div><button data-action="currencies">Monedas y equivalencias</button><div id="payment-result"></div></div></details><div class="row"><button data-action="cart-export" ${lines.length?'':'disabled'}>↓ TXT</button><button data-action="cart-clear" ${lines.length?'':'disabled'}>Vaciar</button></div><p class="subtle">Consulta de compra, sin registrar pagos, billeteras ni caja del comerciante.</p></div></details>`;renderPayment();}
function renderPayment(){if(!$('payment-result'))return;const sum=payable();if(sum.pending){$('payment-result').innerHTML='<p class="notice">Completá los precios pendientes para calcular el vuelto.</p>';return;}try{const r=C.currencyPayment(sum.amount,shop().payment||{},db);if(r.short){$('payment-result').innerHTML=`<p class="notice">Faltan ${esc(pretty(r.short))}.</p>`;return;}const change=changeOverride||r.change;$('payment-result').innerHTML=`<p>Vuelto: <strong>${esc(C.currencyText(r.change,coinRegistry()))}</strong></p><details class="fold"><summary>Cambiar combinación de monedas</summary><div class="payment-grid">${paymentFields('change',change)}</div><p id="change-check" class="subtle">La combinación debe sumar ${esc(pretty((C.currencyValue(r.change,coinRegistry()))/100))}.</p></details>`;}catch(err){$('payment-result').innerHTML=`<p class="notice">${esc(err.message)}</p>`;}}
function renderCraft(){const items=available().filter(e=>e.type==='item');if(!items.some(e=>e.id===craftSelection))craftSelection=items.find(e=>e.craftMode==='common')?.id||items[0]?.id;const e=find(craftSelection);$('view').innerHTML=`<div class="work-grid craft-grid"><section class="panel"><div class="panel-body field-stack"><div class="row"><button data-action="new-craft">Crear objeto nuevo</button><button data-action="random-craft">⚄ Crear al azar</button></div><label>Objeto<select id="craft-item">${groupedEntryOptions(items,craftSelection)}</select></label><div class="form-grid">${input('craft-qty','Cantidad',craftQty,'type="number" min="1" max="10000"')}<label>Regla del fabricante (opcional)<select id="craft-maker">${options([['','Referencia general'],...merchants().map(m=>[m.id,m.name])],craftMaker)}</select></label></div><details class="fold" ${e?.needsBase||e?.craftMode==='scroll'?'open':''}><summary>Objeto base y componentes</summary><div class="fold-content field-stack">${e?.needsBase?`<label>Objeto base<select id="craft-base">${groupedEntryOptions(items.filter(e=>!e.magic),craftBase,'Elegir…',true)}</select></label><label>Cómo se obtiene la base<select id="base-mode">${options([['buy','Comprar'],['make','Fabricar'],['owned','Ya disponible · sin cargo de base']],baseOwned?'owned':makeBase?'make':'buy')}</select></label>`:''}${e?.craftMode==='scroll'?`<label>Nivel del conjuro<select id="scroll-level">${options(Array.from({length:10},(_,i)=>[i,i?'Nivel '+i:'Truco']),scrollLevel)}</select></label>`:''}${input('craft-extras','Componentes adicionales por unidad (PO)',craftExtras,'type="number" min="0" max="1000000000" step="0.01"')}<p class="subtle">Solo costos no incluidos en la receta. Los componentes reutilizables se informan aparte; el DM decide su disponibilidad.</p></div></details><div id="craft-result"></div></div></section><section class="panel"><div class="panel-body"><h2>${esc(e?.name||'Objeto')}</h2>${e?tag(e)+hb(e):''}<div class="description sheet">${e?sheet(e):''}</div>${originalHTML(e||{})}<p class="source">${esc(e?.origin||'')}</p><div class="row"><button data-action="clone-entry" data-id="${esc(e?.id||'')}">Crear homebrew</button><button data-action="imbue-entry" data-id="${esc(e?.id||'')}">Imbuir magia</button></div></div></section></div>`;renderCraftResult();}
function renderCraftResult(){const e=find(craftSelection);if(!e)return;const r=C.craft(e,db.merchants.find(m=>m.id===craftMaker)||null,craftQty,{extras:craftExtras,base:find(craftBase),makeBase,baseOwned,scrollLevel});$('craft-result').innerHTML=r.error?`<div class="notice">${esc(r.error)} La herramienta informa requisitos; no comprueba inventarios del fabricante.</div>`:`<div class="calc-result"><h2>Entrega en ${r.days} ${r.days===1?'día':'días'}</h2><div class="compact-line"><span>Materias primas / receta</span><strong>${esc(pretty(r.materials))}</strong></div>${baseOwned&&e.needsBase?'<div class="compact-line"><span>Base ya disponible</span><span>Sin cargo adicional</span></div>':''}${r.baseCost?`<div class="compact-line"><span>Objeto base · ${makeBase?'fabricación':'compra'}</span><span>${esc(pretty(r.baseCost))}</span></div>`:''}${r.extras?`<div class="compact-line"><span>Componentes adicionales</span><span>${esc(pretty(r.extras))}</span></div>`:''}<div class="compact-line"><span>Total de fabricación</span><strong>${esc(pretty(r.total))}</strong></div><div class="compact-line"><span>Precio de venta de referencia</span><span>${esc(pretty(r.purchase))}</span></div><label>Venta total decidida por el DM (PO) · opcional<input id="craft-sale" type="number" min="0" max="1000000000" step="0.01" value="${craftSale??''}" placeholder="Usar referencia"></label><div class="compact-line"><span>Margen bruto del comerciante</span><strong id="craft-margin">${esc(pretty((craftSale??r.purchase)==null?null:(craftSale??r.purchase)-r.total))}</strong></div><p class="subtle">Venta menos fabricación. No descuenta otros gastos ni inventa una tarifa de mano de obra.</p><details class="fold"><summary>Elementos y costos</summary><p class="description">${esc(e.componentsNote||'La receta fija un presupuesto de materias primas; esta ficha todavía no detalla materiales y cantidades. Podés anotarlos al crear homebrew.')}</p><div class="compact-line"><span>Materias primas · presupuesto de receta</span><span>${esc(C.money(r.materials))}</span></div>${r.baseCost?`<div class="compact-line"><span>${esc(find(craftBase)?.name||'Objeto base')} · ${makeBase?'fabricar':'comprar'}</span><span>${esc(C.money(r.baseCost))}</span></div>`:''}${r.extras?`<div class="compact-line"><span>Componentes adicionales</span><span>${esc(C.money(r.extras))}</span></div>`:''}<p class="subtle">Los materiales anotados están incluidos en la receta; solo los extras se suman aparte. Las herramientas son reutilizables.</p></details><details class="fold"><summary>Requisitos y referencia</summary><p class="subtle">${esc(r.rule)} · 8 horas por día.<br>Herramienta: ${esc(r.tool)}<br>${r.requirements.map(esc).join('<br>')}<br>Sin validar herramientas, competencias ni materiales del comerciante. Decide el DM.</p></details></div><p class="subtle">Herramientas reutilizables no se cobran en cada fabricación. El precio de venta es distinto del costo de elaboración. No se registran encargos ni fechas.</p>`;}
function contextHTML(){const s=db.settings;return `<details class="context-line"><summary>Party ${s.level} · VD ${s.cr} · ${s.kind==='personal'?'Tesoro personal ×'+s.count:'Tesoro acumulado'} · Cambiar</summary><div class="fold-content"><div class="form-grid">${input('loot-level','Nivel de la party',s.level,'data-setting="level" type="number" min="1" max="20"') }<label>VD de referencia<select data-setting="cr">${options([0,.125,.25,.5,...Array.from({length:30},(_,i)=>i+1)].map(n=>[n,n]),s.cr)}</select></label><label>Tesoro<select data-setting="kind">${options([['personal','Personal'],['hoard','Acumulado']],s.kind)}</select></label>${input('loot-count','Criaturas similares (personal)',s.count,'data-setting="count" type="number" min="1" max="100"')}</div><p class="subtle">VD calcula riqueza y cantidad de mágicos; nivel de party elige rareza. Para acumulado, usar el VD de la criatura principal.</p></div></details>`;}
function manualHTML(){const s=db.settings,t=C.tier(s.level),w=s.autoWeights?C.WEIGHTS[t]:s.weights,max=[2,3,4,4][t];return `<details class="fold"><summary>Preparar loot manualmente</summary><div class="fold-content field-stack"><label>Nombre<div class="row"><input data-setting="title" id="loot-title" maxlength="160" placeholder="Nombre opcional" value="${esc(s.title)}" style="flex:1"><button data-action="random-name" type="button" aria-label="Nombre aleatorio">⚄</button></div></label><label>Fuente<select data-setting="source">${options(['Cofre','Enemigo','Grupo','Otro'].map(x=>[x,x]),s.source)}</select></label><label>Dificultad<select data-setting="difficulty">${options(['Trivial','Fácil','Media','Difícil','Mortal'].map(x=>[x,x]),s.difficulty)}</select></label><label>Multiplicador de riqueza <output>${s.ratio}×</output><input data-setting="ratio" type="range" min="0" max="10" step="0.1" value="${s.ratio}"></label><label>Probabilidad de magia por oportunidad <output>${s.magicPct}%</output><input data-setting="magicPct" type="range" min="0" max="100" value="${s.magicPct}"></label>${input('max-magic','Máximo de objetos mágicos',s.maxMagic,'data-setting="maxMagic" type="number" min="0" max="20"')}<details class="fold"><summary>Rarezas y reglas propias</summary><label class="check"><input data-setting="autoWeights" type="checkbox" ${s.autoWeights?'checked':''}>Distribución según nivel · DMG</label><p class="subtle">Máximo: ${C.RARITIES[max]}. Los pesos no determinan si aparece magia.</p><div class="weights">${C.RARITIES.map((r,i)=>`<label class="weight-row"><span>${esc(r)}</span><input data-weight="${i}" type="number" min="0" max="1000" value="${i>max?0:w[i]}" ${s.autoWeights||i>max?'disabled':''} aria-label="Peso ${r}"></label>`).join('')}</div></details><details class="fold"><summary>Artefactos propios · excepción explícita</summary><label class="check"><input data-setting="artifacts" type="checkbox" ${s.artifacts?'checked':''}>Permitir artefactos propios fuera del límite de rareza</label>${input('artifact-pct','Probabilidad de artefacto al obtener magia (%)',s.artifactPct,'data-setting="artifactPct" type="number" min="0" max="100"')}</details><button class="primary" data-action="generate-manual">Generar loot</button><button class="text-button" data-action="reset-loot">Restablecer parámetros</button><p class="subtle">Reglas propias: aplica riqueza y dificultad sobre el presupuesto DMG. Cada oportunidad tiene la probabilidad indicada; pueden salir de 0 al máximo. Gemas y arte sustituyen monedas; no aumentan el total.</p></div></details>`;}
function renderLoot(){const history=db.loot.filter(l=>l.campaign===db.campaign&&!db.hiddenLoot.includes(l.id));$('view').innerHTML=`<div class="work-grid"><aside class="panel"><div class="panel-body">${contextHTML()}<button class="primary full" style="margin:0" data-action="generate-quick">⚄ Generar rápido · DMG</button><p class="subtle">Usa solo el contexto. Ignora los ajustes manuales.</p>${manualHTML()}</div></aside><section id="loot-output"><div class="tools-row"><input id="loot-search" type="search" aria-label="Buscar resultados" placeholder="Buscar resultados…"><button data-action="clean-screen">Limpiar pantalla</button><button data-action="show-history">Ver historial</button><button data-action="clean-history">Limpiar historial</button></div><div id="history">${history.map(historyHTML).join('')||'<div class="empty">Generá el primer resultado.</div>'}</div></section></div>`;}
function historyHTML(l){return `<details class="loot-card" data-loot-id="${esc(l.id)}" ${latest===l.id?'open':''}><summary><strong>${esc(l.title||'Resultado de loot')}</strong><span>${esc(l.saved?'☆ ':'')}${esc(l.mode||'Legado')} · ${esc(new Date(l.date).toLocaleDateString('es-AR'))}</span></summary><div class="loot-content"><p class="subtle">${esc(l.context||'Resultado conservado del prototipo anterior')}</p>${l.coins?`<div class="compact-line"><span>Monedas</span><span>${esc(displayCoins(l.coins))}</span></div>${l.valuables.length?'<h3>Gemas / arte</h3>'+l.valuables.map(e=>`<div class="compact-line"><span>${esc(e.name)}</span><span>${esc(C.money(e.price))}</span></div>`).join(''):''}<div class="compact-line"><span>Tesoro monetario total</span><strong>${esc(C.money(l.budget))}</strong></div>`:''}${l.items.filter(e=>!e.magic).length?'<h3>Otros objetos</h3>':''}${l.items.filter(e=>!e.magic).map(e=>`<div class="compact-line"><span>${esc(e.name)} ${hb(e)}<span class="mundane-description">${esc(e.description)}${e.attributes?'<br>'+esc(e.attributes):''}</span></span><span>${esc(pretty(e.price))}</span></div>`).join('')}${l.items.filter(e=>e.magic).map(e=>`<div class="loot-magic"><strong>${esc(e.name)}</strong> ${tag(e)} ${hb(e)}<div class="description sheet">${sheet(e)}</div><p class="source">${esc(e.origin)} · ${esc(pretty(e.price))}</p></div>`).join('')}${(l.warnings||[]).map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<div class="result-actions"><button data-action="save-list" data-id="${esc(l.id)}">${l.saved?'★ Lista guardada':'☆ Guardar lista'}</button><button data-action="loot-txt" data-id="${esc(l.id)}">↓ TXT</button><button data-action="delete-loot" data-id="${esc(l.id)}">Eliminar</button></div></div></details>`;}
function storeResult(result,title){const l={...result,id:C.uid(),campaign:db.campaign,date:new Date().toISOString(),title,saved:false};db.loot.unshift(l);latest=l.id;save();if(view==='loot')renderLoot();else renderDice();const target=document.querySelector(`[data-loot-id="${l.id}"]`);if(target){target.open=true;target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});}toast('Resultado generado y guardado.');}
function renderDice(){if(!db.equipmentTable){db.equipmentTable=C.equipmentTable(window.TABLE_DATA);save();}const d=db.dice,rows=d.family==='equipo'?db.equipmentTable:window.TABLE_DATA.tables[(d.family==='azar'?'armamento':d.family)+'|'+d.rarity];const last=db.loot.find(l=>l.campaign===db.campaign&&['D100','Sorteo'].includes(l.mode));$('view').innerHTML=`<div class="work-grid"><section class="panel"><div class="panel-body field-stack"><label>Familia<select id="dice-family">${options(Object.entries(families),d.family)}</select></label><label>Rareza · decide el DM<select id="dice-rarity" ${d.family==='equipo'?'disabled':''}>${options(C.RKEYS.map((r,i)=>[r,C.RARITIES[i]]),d.rarity)}</select></label><button class="primary" data-action="dice-roll">Tirar D100</button><div class="form-grid">${input('physical-d100','D100 físico · 00 = 100',diceInputs.d100,'inputmode="numeric" maxlength="3"')}${input('physical-d4','D4 físico · opcional',diceInputs.d4,'type="number" min="1" max="4"')}</div><button data-action="dice-physical">Resolver dado físico</button><details class="fold"><summary>Tabla y equipo</summary><div class="fold-content"><p class="subtle">${d.family==='azar'?'Vista previa: Armamento. La familia se sortea al resolver.':'Rangos de las tablas de referencia DMG / SRD conservados del HTML recibido; cotejo editorial pendiente.'}</p>${rows.map(r=>`<div class="compact-line"><span>${r.start===r.end?r.start:r.start+'–'+r.end}</span><span>${esc(r.name)}</span></div>`).join('')}${d.family==='equipo'?'<button data-action="equipment-renew">Regenerar posiciones 83–100</button>':''}</div></details><details class="fold"><summary>Elegir un objeto al azar</summary><div class="fold-content field-stack"><label>Rareza<select id="draw-rarity">${options([['all','Todas'],...C.RARITIES.map(r=>[r,r])],diceInputs.rarity)}</select></label><label class="check"><input id="draw-artifacts" type="checkbox" ${diceInputs.artifacts?'checked':''}>Incluir artefactos propios</label><button data-action="catalog-draw">Sortear un objeto</button><p class="subtle">Elección uniforme de toda la biblioteca habilitada; no tira D100 ni usa sus familias o rangos. Solo aplica los filtros de esta sección.</p></div></details></div></section><section>${last?historyHTML(last):'<div class="empty">Resultado de la próxima tirada.</div>'}<p class="subtle">D100 usa los rangos de la tabla de familia y rareza elegida. El D4 solo elige familia al azar. «Elegir un objeto al azar» sortea directamente la biblioteca, con sus propios filtros.</p><p class="subtle">D100 y catálogo consultan la biblioteca compartida. Si una ficha está excluida, se informa sin cambiar la tirada.</p></section></div>`;}
function resolveDice(value,physical=false){const d=db.dice;if(!Number.isInteger(value)||value<1||value>100){toast('D100 debe ser de 1 a 100; 00 equivale a 100.');return;}let family=d.family,d4=null;if(family==='azar'){d4=physical&&$('physical-d4').value!==''?Number($('physical-d4').value):C.roll(1,4);if(!Number.isInteger(d4)||d4<1||d4>4){toast('D4 debe ser de 1 a 4.');return;}family=['armamento','instrumentos','arcanos','reliquias'][d4-1];}const rows=family==='equipo'?db.equipmentTable:window.TABLE_DATA.tables[family+'|'+d.rarity],row=rows.find(r=>value>=r.start&&value<=r.end);let e=available().find(e=>e.id===row.itemId)||available().find(e=>e.replacement&&e.parent===row.itemId);if(family==='equipo'){e=available().find(e=>e.type==='item'&&C.norm(e.name)===C.norm(row.name));if(!e&&db.campaign==='romanance'&&/^poción de curación$/i.test(row.name))e=find('romanance:rocio');}const warnings=[];if(!e){warnings.push('Ficha excluida o pendiente de enlace en la biblioteca. Se conserva el resultado original: '+row.name);e={id:'reference:'+family+':'+row.start,name:row.name,description:'Referencia pendiente de enlace y cotejo.',origin:'Tabla recibida · DMG/SRD',price:null,magic:family!=='equipo',rarity:C.RARITIES[C.RKEYS.indexOf(d.rarity)]};}storeResult({items:[C.snapshot(e)],warnings,mode:'D100',context:`${families[family]} · D100 ${value} · rango ${row.start}–${row.end}${d4?' · D4 '+d4:''} · original: ${row.name}`},'D100 · '+row.name);}
function renderContexts(){$('view').innerHTML=`<div class="tools-row"><select id="context-selector" aria-label="Seleccionar contexto">${options(db.campaigns.map(c=>[c.id,c.name]),db.campaign)}</select><button data-action="new-context">＋ Contexto</button><button data-action="currencies">Monedas y equivalencias</button></div><p class="subtle">Solo disponibilidad y activación de contenido. No es un gestor de campañas.</p><h3>Homebrew disponible en este contexto</h3>${accessible().filter(isHB).map(e=>`<label class="check"><input type="checkbox" data-active="${esc(e.id)}" ${!(db.disabled[db.campaign]||[]).includes(e.id)?'checked':''}>${esc(e.name)} ${e.replacement?'· modificación de referencia':''}</label>`).join('')||'<p class="subtle">Sin contenido propio disponible.</p>'}`;}
function renderHelp(){$('view').innerHTML=`<div class="tools-row"><button data-action="export-backup">↓ Respaldo completo</button><button data-action="restore-backup">↑ Restaurar respaldo</button><button data-action="import-content">Importar contenido</button><button data-action="export-all-own">Exportar contenido propio</button></div><details class="fold"><summary>Respaldo e intercambio</summary><p>El respaldo conserva contextos, comerciantes, stock, compras, preferencias, contenido propio, listas propias e historial. Restaurarlo reemplaza el estado actual con confirmación. Los respaldos 0.1 se migran sin borrar sus datos.</p><p>Un paquete compartido contiene solo las fichas propias seleccionadas y su procedencia; no incluye compras, historial ni nombres de campañas. Al importar elegís su alcance. Los IDs coincidentes se omiten o se copian con otro ID; no se sobrescriben. El contenido importado queda desactivado hasta habilitarlo desde Contexto.</p></details><details class="fold"><summary>Loot rápido y manual</summary><p>Rápido usa tesoro personal/acumulado por VD y rareza por nivel del DMG 2024 (pp. 120–121 y 218). Personal no agrega mágicos automáticamente; acumulado usa su cantidad de tabla. El reparto en monedas, gemas y arte es una presentación del generador dentro del presupuesto.</p><p>Manual permite modificar riqueza, dificultad, probabilidad y máximo de mágicos. Esas modificaciones son reglas propias. Cada oportunidad puede fallar; el máximo no garantiza cantidad. Las rarezas superiores al rango quedan excluidas, salvo artefactos propios expresamente habilitados. Magia y equipo se informan fuera del tesoro monetario.</p><p>Todo resultado se guarda. «Guardar lista» lo protege al limpiar historial. Limpiar pantalla solo oculta; Ver historial recupera la vista.</p></details><details class="fold"><summary>Biblioteca y homebrew</summary><p>La base se conserva. Creá variantes independientes o modificaciones de una referencia con alcance global o por campañas. El original queda visible. No se aplican automáticamente efectos narrativos escritos: solo propiedades y cálculos implementados. El formulario habilita los campos del tipo elegido.</p></details><details class="fold"><summary>Listas propias</summary><p>En Biblioteca → Mis listas, elegí una lista de origen en el centro, marcá una o varias fichas a la derecha y usá ← Agregar. Para quitarlas, marcalas en Mi lista y usá Quitar →. Asigná un nombre y pulsá Guardar lista. Las fichas se consultan con ⓘ y conservan su vínculo con el catálogo común.</p><p>La disponibilidad puede ser global o por contextos. El JSON de una lista guarda referencias a la base e incluye las fichas propias necesarias y sus dependencias, sin duplicar el catálogo oficial. Las referencias no instaladas se conservan y se señalan. Importar agrega una lista nueva; no reemplaza las existentes.</p></details><details class="fold"><summary>Fabricación</summary><p>SRD 5.2.1, pp. 112–113 y 226; Manual del Jugador, p. 233; DMG, pp. 220–221. Los costos de receta ya representan materias primas. Objeto base y componentes adicionales se suman por separado; no se inventa un costo de mano de obra. Las herramientas son reutilizables y se muestran como requisitos, sin bloquear por capacidades del comerciante.</p><p>Objetos comunes: mitad del precio en materias primas y precio ÷ 10 en días, jornadas de 8 horas. La calculadora conserva precisión de cobre para la mitad monetaria. Mágicos: costo y tiempo por rareza; consumibles a la mitad excepto pergaminos. Pociones de curación y pergaminos tienen reglas específicas. Los valores pendientes no se convierten en cero.</p></details><details class="fold"><summary>Pago y vuelto</summary><p>1 PPT = 10 PO; 1 PO = 2 PE = 10 PP = 100 PC. Podés pagar mezclando monedas. El vuelto propone una combinación exacta; podés editarla y se comprueba su equivalencia. Oro, plata y cobre están habilitados de base. Platino, electro y monedas propias se muestran y cuentan en el pago únicamente si están habilitados en la configuración del contexto.</p></details><details class="fold"><summary>Fuentes, créditos y límites</summary><p>Idea y dirección: Sarten / Sebas. Diseño e implementación en colaboración: Reldor Dawncaller · ChatGPT / Codex. Prototipo previo realizado con Claude y aportado por Sarten.</p><p>Esta obra incluye material procedente del documento de referencia del sistema 5.2.1 (“SRD 5.2.1”) de Wizards of the Coast LLC, disponible en <a href="https://www.dndbeyond.com/srd" target="_blank" rel="noopener">dndbeyond.com/srd</a>. La licencia sobre el SRD 5.2.1 se concede de acuerdo con la licencia internacional de atribución/reconocimiento 4.0 de Creative Commons, disponible en <a href="https://creativecommons.org/licenses/by/4.0/legalcode" target="_blank" rel="noopener">CC BY 4.0</a>.</p><p>Adaptaciones: extracción, nombres traducidos parcialmente y presentación. Biblioteca en inglés y español durante pruebas; selector bilingüe diferido. Las tablas y referencias exclusivas del DMG permanecen para el prototipo local; no se declara distribuible todo este paquete. Fichas heredadas marcadas para cotejo. No se garantiza balance automático ni se ejecuta código de los JSON.</p><a href="../../fuentes/loot-generator.html" target="_blank" rel="noopener">Abrir HTML original 1.2</a></details>`;}
function scopeFields(scope=[],prefix='edit'){return `<fieldset><legend>Disponibilidad</legend><label class="check"><input id="${prefix}-global" type="checkbox" ${scope.length?'':'checked'}>Global · todos los contextos</label><div class="row">${db.campaigns.map(c=>`<label class="check"><input name="${prefix}-scope" type="checkbox" value="${esc(c.id)}" ${scope.includes(c.id)?'checked':''} ${scope.length?'':'disabled'}>${esc(c.name)}</label>`).join('')}</div></fieldset>`;}
function getScope(prefix){const global=$(prefix+'-global').checked,scope=global?[]:[...document.querySelectorAll(`[name="${prefix}-scope"]:checked`)].map(n=>n.value);if(!global&&!scope.length)throw Error('Elegí al menos un contexto o disponibilidad global.');return scope;}
function toolOptions(current=''){const tools=all().filter(e=>e.type==='item'&&e.category==='Herramientas').map(e=>e.name);for(const t of ['Herramientas de herrero','Kit de herbolario'])if(!tools.includes(t))tools.push(t);if(current&&!tools.includes(current))tools.push(current);return options([['','Asignar según objeto / decide el DM'],...tools.sort().map(t=>[t,t]),['other','Definir otra…']],current);}
function groupedEntryOptions(entries,value,empty='Elegir…',price=false){const groups=[...new Set(entries.map(C.referenceGroup))].sort((a,b)=>a.localeCompare(b,'es'));return options([['',empty]],value)+groups.map(group=>`<optgroup label="${esc(group)}">${options(entries.filter(e=>C.referenceGroup(e)===group).sort((a,b)=>a.name.localeCompare(b.name,'es')).map(e=>[e.id,e.name+(price?' · '+pretty(e.price):e.magic?' · '+(e.rarity||'mágico'):'')]),value)}</optgroup>`).join('');}
function referenceEntries(type){return accessible().filter(e=>e.type===type&&e.id!==editing?.id);}
function referenceOptions(type,current='',group='all',term=''){return groupedEntryOptions(referenceEntries(type).filter(e=>(group==='all'||C.referenceGroup(e)===group)&&(!term||C.norm(e.name+' '+(e.english||'')).includes(C.norm(term)))),current,'Sin referencia');}
function referenceControls(type,parent){const base=find(parent),group=base?C.referenceGroup(base):'all';return `<div id="reference-controls" class="form-grid"><label>Tipo de referencia<select id="entry-reference-group">${options([['all','Todos los tipos'],...[...new Set(referenceEntries(type).map(C.referenceGroup))].sort((a,b)=>a.localeCompare(b,'es')).map(x=>[x,x])],group)}</select></label>${input('entry-reference-search','Buscar referencia','','type="search"')}</div>`;}
function filterReferences(){const current=$('entry-parent').value;$('entry-parent').innerHTML=referenceOptions($('entry-type').value,current,$('entry-reference-group').value,$('entry-reference-search').value);}
function openEditor(id=null,clone=false){editorPurpose='create';const e=id?find(id):null;savedMagicSpell=structuredClone(e?.magicSpell||null);editing=e?.id.startsWith('custom:')&&!clone?structuredClone(e):null;const type=e?.type||'item',base=e&&!editing?e:null,parent=editing?.parent||base?.id||'';
 $('editor-title').textContent=editing?'Editar homebrew':'Crear homebrew';
 $('editor-fields').innerHTML=`<div class="form-grid"><label>Tipo<select id="entry-type">${options(Object.entries(C.TYPES),type)}</select></label><label>Acción<select id="entry-action">${options([['variant','Contenido nuevo a partir de la referencia'],['replace','Reemplazar la referencia en los contextos elegidos']],editing?.replacement||base&&!clone?'replace':'variant')}</select></label></div>${referenceControls(type,parent)}<label>Referencia base<select id="entry-parent">${referenceOptions(type,parent,find(parent)?C.referenceGroup(find(parent)):'all')}</select></label>${input('entry-name','Nombre',e?(clone?e.name+' · homebrew':e.name):'','required maxlength="180"')}<div class="form-grid"><label>Categoría<select id="entry-category">${options([['Equipo','Equipo'],['Armas','Armas'],['Armaduras','Armaduras'],['Herramientas','Herramientas'],['Objetos mágicos','Objetos mágicos'],['Comida','Comida'],['Bebidas','Bebidas'],['Alojamiento','Alojamiento'],['Alquileres','Alquileres'],['Transporte','Transporte'],['Contratación','Contratación'],['Servicios mágicos','Servicios mágicos'],['Otra','Otra']],['Equipo','Armas','Armaduras','Herramientas','Objetos mágicos','Comida','Bebidas','Alojamiento','Alquileres','Transporte','Contratación','Servicios mágicos'].includes(e?.category||'Equipo')?(e?.category||'Equipo'):'Otra')}</select></label>${input('entry-category-other','Categoría propia',e?.category||'','maxlength="100"')}</div><label>Descripción / efectos<textarea id="entry-description" rows="5" maxlength="30000" required>${esc(e?.description||'')}</textarea></label><label>Atributos, requisitos o progresión<textarea id="entry-attributes" rows="2" maxlength="5000">${esc(e?C.uniqueAttributes(e):'')}</textarea></label><div class="price-action-row" data-types="item service">${input('entry-price','Precio unitario (PO) · vacío = pendiente',e?.price??'','type="number" min="0" max="1000000000" step="0.01"')}<div data-types="item"><button type="button" data-action="magic-price">Usar valor por rareza · SRD</button></div></div><div data-types="monster"><div class="form-grid"><label>VD<select id="monster-cr">${options(crOptions(),e?.monster?.cr||'1')}</select></label>${input('monster-xp','PX',e?.monster?.xp??200,'type="number" min="0" max="10000000" step="1"')}</div><button type="button" data-action="monster-xp">Usar PX por VD</button><div class="form-grid">${input('monster-kind','Tipo de criatura',e?.monster?.creatureType||'','maxlength="1000"')}${input('monster-ac','CA',e?.monster?.ac||'','maxlength="1000"')}${input('monster-hp','Puntos de golpe',e?.monster?.hp||'','maxlength="1000"')}${input('monster-speed','Velocidades',e?.monster?.speed||'','maxlength="1000"')}${input('monster-lair','PX en guarida · opcional',e?.monster?.lairXp??'','type="number" min="0" max="10000000" step="1"')}</div><details class="fold"><summary>Editar la ficha de criatura</summary><p class="subtle">VD y PX se usan en Encuentros. Ataques, rasgos y el resto del bloque se editan en Descripción; cambiar VD no reescribe ni equilibra esas estadísticas.</p></details></div><div data-types="service">${input('entry-unit','Unidad de cobro',e?.unit||'día','maxlength="100" list="service-units"')}<datalist id="service-units"><option value="día"><option value="noche"><option value="comida"><option value="jarra"><option value="botella"><option value="viaje"><option value="km"><option value="lanzamiento"></datalist></div><div data-types="spell"><div class="form-grid"><label>Nivel<select id="spell-level">${options(Array.from({length:10},(_,i)=>[i,i?'Nivel '+i:'Truco']),e?.spell?.level??e?.level??0)}</select></label><label>Escuela<select id="spell-school">${options(['Por definir','Abjuración','Adivinación','Conjuración','Encantamiento','Evocación','Ilusión','Nigromancia','Transmutación'].map(s=>[s,s]),e?.spell?.school||'Por definir')}</select></label>${input('spell-casting','Tiempo de lanzamiento',e?.spell?.casting||'','maxlength="1000"')}${input('spell-range','Alcance',e?.spell?.range||'','maxlength="1000"')}${input('spell-components','Componentes',e?.spell?.components||'','maxlength="1000"')}${input('spell-duration','Duración',e?.spell?.duration||'','maxlength="1000"')}</div></div><div data-types="item">${magicSpellFields(e)}<label id="entry-magic-effect-label">Propiedad mágica / habilidades<textarea id="entry-magic-effect" rows="3" maxlength="5000" placeholder="Qué hace, cómo se activa y sus límites. Elegir rareza o precio no agrega un efecto.">${esc(e?.magicEffect||'')}</textarea></label><p id="entry-magic-effect-help" class="subtle">Sin bono también puede tener magia. Definí el efecto o usá una ficha mágica como referencia. Las habilidades nuevas requieren revisión del DM.</p><label>Bonificación mágica de referencia<select id="entry-bonus">${options([[0,'Sin bonificador'],[1,'+1'],[2,'+2'],[3,'+3'],[4,'+4 · diseño DMG / legendario'],[5,'+5 · homebrew']],e?.enhancementBonus||0)}</select></label><details class="fold"><summary>Referencia de bonificaciones</summary><p class="subtle">Armas y escudos: +1 infrecuente, +2 raro, +3 muy raro. Armaduras: +1 raro, +2 muy raro, +3 legendario. La guía de diseño del DMG admite +4 en legendarios. +5 queda fuera de esa guía y requiere receta de mesa. Otras habilidades escritas requieren revisión del DM.</p></details><label>Elementos de la receta · incluidos en su costo<textarea id="entry-components" rows="2" maxlength="5000" placeholder="Materiales, cantidades y componentes conocidos; no inventar desglose del manual">${esc(e?.componentsNote||'')}</textarea></label><div class="form-grid"><label>Rareza<select id="entry-rarity">${options(['Mundano',...C.RARITIES,'Artefacto','Por revisar'].map(r=>[r,r]),e?.rarity||'Mundano')}</select></label><label>Fabricación<select id="entry-craft">${options([['none','Sin receta asignada'],['common','Objeto no mágico · SRD'],['magic','Objeto mágico · SRD'],['healing','Poción de curación · SRD'],['scroll','Pergamino · SRD'],['manual','Receta propia']],e?.craftMode||'none')}</select></label></div><label>Herramienta de referencia<select id="entry-tool">${toolOptions(e?.tool||'')}</select></label><label id="other-tool-label" hidden>Otra herramienta<input id="other-tool" maxlength="100"></label><div id="manual-recipe" class="form-grid">${input('entry-days','Días por unidad',e?.days??'','type="number" min="0.01" max="100000" step="0.01"')}${input('entry-materials','Materias primas por unidad (PO)',e?.materials??'','type="number" min="0" max="1000000000" step="0.01"')}</div><label class="check"><input id="entry-magic" type="checkbox" ${e?.magic?'checked':''}>Objeto mágico</label><label class="check"><input id="entry-consumable" type="checkbox" ${e?.consumable?'checked':''}>Consumible</label><label class="check"><input id="entry-needs-base" type="checkbox" ${e?.needsBase?'checked':''}>Requiere objeto base para fabricación mágica</label><label class="check"><input id="entry-loot" type="checkbox" ${e?.loot?'checked':''}>Disponible en loot</label></div><div id="entry-craft-preview" data-types="item"></div>${scopeFields(e?.scope||[])}<details class="fold"><summary>Autoría y procedencia para compartir</summary><div class="fold-content form-grid">${input('entry-author','Autoría',e?.metadata?.author||'','maxlength="1000"')}${input('entry-version','Versión del contenido',e?.metadata?.version||'1','maxlength="1000"')}${input('entry-license','Condiciones de uso',e?.metadata?.license||(base?'Incluye material de referencia; revisar condiciones antes de compartir.':'No declaradas'),'maxlength="1000"')}${input('entry-source','Procedencia',e?.metadata?.source||e?.origin||'Contenido propio','maxlength="1000"')}</div></details><p class="subtle">Los campos no aplicables se deshabilitan y no afectan cálculos. La base permanece conservada. Los efectos escritos no se convierten en código ejecutable.</p>`;
 updateEditor();$('editor').showModal();}
function updateEditor(){const type=$('entry-type').value;document.querySelectorAll('[data-types]').forEach(group=>{const enabled=group.dataset.types.split(' ').includes(type);group.hidden=!enabled;group.querySelectorAll('input,select,textarea').forEach(e=>e.disabled=!enabled);});const magical=type==='item'&&$('entry-magic').checked;$('entry-magic-effect-label').hidden=!magical;$('entry-magic-effect-help').hidden=!magical;$('entry-magic-effect').disabled=!magical;const manual=type==='item'&&$('entry-craft').value==='manual';$('manual-recipe').hidden=!manual;$('manual-recipe').querySelectorAll('input').forEach(e=>e.disabled=!manual);const otherTool=type==='item'&&$('entry-tool').value==='other';$('other-tool-label').hidden=!otherTool;$('other-tool').disabled=!otherTool;const other=$('entry-category').value==='Otra';$('entry-category-other').closest('label').hidden=!other;$('entry-category-other').disabled=!other;updateMagicControls();renderEditorCraft();}
function applyBonus(){const bonus=Number($('entry-bonus').value);if(!bonus)return;const base=find($('entry-parent').value),category=$('entry-category').value;try{const profile=C.bonusProfile(category,base?.name||$('entry-name').value,bonus);$('entry-magic').checked=true;if(profile.homebrew){$('entry-craft').value='manual';$('entry-rarity').value='Por revisar';$('entry-price').value='';$('entry-days').value='';$('entry-materials').value='';toast('+5: definí rareza y receta propia; queda fuera de la guía de diseño del DMG.');}else{$('entry-craft').value='magic';if(C.RARITIES.indexOf($('entry-rarity').value)<C.RARITIES.indexOf(profile.rarity))$('entry-rarity').value=profile.rarity;}$('entry-needs-base').checked=true;}catch(err){$('entry-bonus').value='0';toast(err.message);}updateEditor();}
function magicSpellFields(e){const spell=e?.magicSpell,mode=spell?(e.magicEffect?'both':'spell'):e?.magicEffect?'ability':'none';return `<div id="magic-property-controls"><label>Propiedad adicional<select id="magic-property-mode">${options([['none','Sin propiedad adicional'],['spell','Conjuro de la biblioteca'],['ability','Aptitud mágica'],['both','Conjuro y aptitud']],mode)}</select></label><div id="entry-spell-panel" class="field-stack"><label>Buscar conjuro<input id="magic-spell-search" type="search" placeholder="Nombre del conjuro"></label><label>Conjuro<select id="magic-spell"></select></label><div class="form-grid"><label>Activación<select id="magic-activation">${options(['Según el conjuro','Acción de magia','Acción adicional','Reacción','Al llevarlo puesto','Otra · detallar en condiciones'].map(x=>[x,x]),spell?.activation||'Según el conjuro')}</select></label><label>Uso<select id="magic-usage">${options([['daily','Usos diarios'],['charges','Cargas'],['atwill','A voluntad'],['consumed','Se consume al lanzarlo']],spell?.usage||'daily')}</select></label></div><div class="form-grid" id="magic-limited-use">${input('magic-uses','Usos / cargas',spell?.uses||1,'type="number" min="1" max="1000" step="1"')}<label>Recuperación<select id="magic-recovery">${options(['Al amanecer','Tras descanso largo','No recupera','Otra · detallar en condiciones'].map(x=>[x,x]),spell?.recovery||'Al amanecer')}</select></label></div><label>Condiciones y límites<textarea id="magic-spell-notes" rows="2" maxlength="5000">${esc(spell?.notes||'')}</textarea></label></div></div>`;}
function renderSpellOptions(){const node=$('magic-spell');if(!node)return;const selected=node.value||savedMagicSpell?.id||'',term=C.norm($('magic-spell-search').value),spells=available().filter(e=>e.type==='spell'&&(e.id===selected||C.norm(e.name+' '+(e.english||'')).includes(term)));if(savedMagicSpell&&!spells.some(e=>e.id===savedMagicSpell.id))spells.unshift({...savedMagicSpell,type:'spell'});node.innerHTML=options([['','Elegir conjuro…'],...spells.map(e=>[e.id,e.name+' · '+(Number(e.spell?.level??e.level??0)?'nivel '+Number(e.spell?.level??e.level):'truco')])],selected);}
function readMagicSpell(required=false){if(!$('entry-magic').checked||!['spell','both'].includes($('magic-property-mode').value))return null;const source=find($('magic-spell').value)||savedMagicSpell;if(!source||source.id!==$('magic-spell').value){if(required)throw Error('Elegí el conjuro que llevará el objeto.');return null;}return{id:source.id,name:source.name,level:Number(source.spell?.level??source.level??0),activation:$('magic-activation').value,usage:$('magic-usage').value,uses:Number($('magic-uses').value||1),recovery:$('magic-recovery').value,notes:$('magic-spell-notes').value.trim()};}
function updateMagicControls(){const on=$('entry-type').value==='item'&&$('entry-magic').checked,mode=$('magic-property-mode').value,spell=on&&['spell','both'].includes(mode),ability=on&&['ability','both'].includes(mode);$('magic-property-controls').hidden=!on;$('magic-property-controls').querySelectorAll('input,select,textarea').forEach(n=>n.disabled=!on);$('entry-spell-panel').hidden=!spell;$('entry-spell-panel').querySelectorAll('input,select,textarea').forEach(n=>n.disabled=!spell);$('entry-magic-effect-label').hidden=!ability;$('entry-magic-effect').disabled=!ability;$('entry-magic-effect-help').hidden=true;const limited=spell&&['daily','charges'].includes($('magic-usage').value);$('magic-limited-use').hidden=!limited;$('magic-limited-use').querySelectorAll('input,select').forEach(n=>n.disabled=!limited);if(!$('magic-spell').options.length)renderSpellOptions();}
function renderEditorCraft(){const node=$('entry-craft-preview');if(!node||$('entry-type').value!=='item')return;const rarity=$('entry-rarity').value,magic=$('entry-magic').checked,mode=$('entry-craft').value,base=find($('entry-parent').value),draft={type:'item',magic,rarity,craftMode:mode,price:$('entry-price').value===''?null:Number($('entry-price').value),days:$('entry-days').value===''?null:Number($('entry-days').value),materials:$('entry-materials').value===''?null:Number($('entry-materials').value),enhancementBonus:Number($('entry-bonus').value),magicSpell:readMagicSpell(),tool:$('entry-tool').value,needsBase:$('entry-needs-base').checked,consumable:$('entry-consumable').checked},r=C.craft(draft,null,1,{base:base&&!base.magic?base:null,baseOwned:editorPurpose==='imbue',scrollLevel:0}),limit=C.DESIGN_LIMITS[C.RARITIES.indexOf(rarity)];node.innerHTML=(r.error?`<p class="subtle">${esc(r.error)}</p>`:`<p class="subtle">${esc(C.money(r.total))} de fabricación · ${r.days} días.</p>`)+C.magicGuidance(draft).map(w=>`<p class="notice">${esc(w)}</p>`).join('')+(magic&&limit?`<details class="fold" data-fold="magic-design-guide"><summary>Guía de rareza</summary><p class="subtle">${esc(rarity)}: conjuro hasta nivel ${limit.spell}; bonificador máximo ${limit.bonus?'+'+limit.bonus:'ninguno'}. Son máximos de diseño, no beneficios automáticos. Revisá el conjunto de propiedades y su frecuencia.</p></details>`:'');}
function prepareImbuing(id){openEditor(id,true);editorPurpose='imbue';const base=find(id);$('editor-title').textContent='Imbuir magia · '+base.name;$('entry-type').closest('.form-grid').hidden=true;$('entry-parent').closest('label').hidden=true;$('reference-controls').hidden=true;$('entry-category').closest('.form-grid').hidden=true;const desc=$('entry-description').closest('label'),attrs=$('entry-attributes').closest('label'),fold=document.createElement('details'),summary=document.createElement('summary');fold.className='fold';summary.textContent='Propiedades del objeto base';fold.append(summary);desc.before(fold);fold.append(desc,attrs);$('entry-magic').checked=true;$('entry-magic').closest('label').hidden=true;if(!base.magic){$('entry-bonus').value='0';$('entry-rarity').value='Común';$('entry-craft').value='magic';$('entry-price').value='';$('entry-needs-base').checked=true;}else{$('entry-craft').value='manual';$('entry-days').value='';$('entry-materials').value='';$('entry-needs-base').checked=false;}updateEditor();}
function saveEntry(event){event.preventDefault();const get=id=>$(id).value.trim(),type=get('entry-type'),priced=['item','service'].includes(type),num=id=>get(id)===''?null:Number(get(id)),parent=get('entry-parent'),base=find(parent);try{const data={...(editing||{}),id:editing?.id||'custom:'+C.uid(),type,parent,replacement:get('entry-action')==='replace'&&!!parent,name:get('entry-name'),category:get('entry-category')==='Otra'?get('entry-category-other'):get('entry-category'),description:get('entry-description'),attributes:get('entry-attributes'),price:priced?num('entry-price'):null,unit:type==='service'?get('entry-unit'):'',scope:getScope('edit'),origin:'Contenido propio · homebrew',status:'Homebrew',magic:type==='item'&&$('entry-magic').checked,rarity:type==='item'?get('entry-rarity'):'Mundano',loot:type==='item'&&$('entry-loot').checked,craftMode:type==='item'?get('entry-craft'):'none',tool:type==='item'?(get('entry-tool')==='other'?get('other-tool'):get('entry-tool')):'',days:type==='item'&&get('entry-craft')==='manual'?num('entry-days'):null,materials:type==='item'&&get('entry-craft')==='manual'?num('entry-materials'):null,consumable:type==='item'&&$('entry-consumable').checked,needsBase:type==='item'&&$('entry-needs-base').checked,metadata:{author:get('entry-author'),version:get('entry-version'),license:get('entry-license'),source:get('entry-source')}};
 if(type==='item'){data.magicEffect=data.magic&&['ability','both'].includes(get('magic-property-mode'))?get('entry-magic-effect'):'';data.magicSpell=data.magic?readMagicSpell(true):null;data.componentsNote=get('entry-components');data.enhancementBonus=Number(get('entry-bonus'));data.bonusEffect='';if(data.enhancementBonus){const profile=C.bonusProfile(data.category,base?.name||data.name,data.enhancementBonus);if(profile.homebrew&&(data.craftMode!=='manual'||!C.RARITIES.includes(data.rarity)&&data.rarity!=='Artefacto'))throw Error('+5 requiere elegir rareza y definir una receta propia.');if(!data.magic||profile.rarity&&C.RARITIES.indexOf(data.rarity)<C.RARITIES.indexOf(profile.rarity))throw Error('La bonificación exige magia y al menos rareza '+profile.rarity+'.');data.bonusEffect=profile.effect;}}else{delete data.magicSpell;delete data.magicEffect;delete data.componentsNote;delete data.enhancementBonus;delete data.bonusEffect;}
 if(type==='item'&&data.magic&&!data.enhancementBonus&&!data.magicEffect&&!data.magicSpell&&!(base?.magic&&data.description.trim()))throw Error('Describí la propiedad mágica: rareza y costo no agregan una habilidad.');
 if(!data.name||!data.description)throw Error('Completá nombre y descripción.');if(data.replacement&&base?.type!==type)throw Error('La modificación debe conservar el tipo de su referencia.');
 if(type==='monster')data.monster={cr:get('monster-cr'),xp:num('monster-xp'),lairXp:num('monster-lair'),creatureType:get('monster-kind'),ac:get('monster-ac'),hp:get('monster-hp'),speed:get('monster-speed')};else delete data.monster;
 if(type==='spell')data.spell=Object.fromEntries(['level','school','casting','range','components','duration'].map(k=>[k,get('spell-'+k)]));else delete data.spell;
 if(data.craftMode==='manual'&&(data.days==null||data.materials==null))throw Error('La receta propia necesita días y materias primas.');if(data.magic&&data.craftMode==='common')throw Error('Un objeto mágico necesita su receta mágica o propia.');
 const next=structuredClone(db),i=next.entries.findIndex(e=>e.id===data.id);i<0?next.entries.push(data):next.entries[i]=data;C.validate(next);for(const c of next.campaigns)C.effective([...window.CATALOG_DATA,...next.entries],c.id,next.disabled);db=next;if(view==='craft'){craftSelection=data.id;craftSale=null;craftBase=base&&!base.magic?base.id:'';baseOwned=editorPurpose==='imbue';makeBase=false;}save();$('editor').close();render();toast('Homebrew guardado; original conservado.');}catch(err){toast(err.message);}}
function randomCreator(){const groups=[...new Set(available().filter(e=>e.type==='item').map(C.referenceGroup))].sort((a,b)=>a.localeCompare(b,'es'));info('Crear al azar',`<form id="random-craft-form" class="field-stack"><label>Tipo de objeto<select id="random-group">${options(groups.map(g=>[g,g]),groups.includes('Armas')?'Armas':groups[0])}</select></label><label>Referencia base · opcional<select id="random-base"></select></label><label class="check"><input id="random-magic" type="checkbox">Mágico</label><button class="primary">Generar borrador editable</button></form>`);renderRandomBases();}
function renderRandomBases(){const group=$('random-group').value;$('random-base').innerHTML=groupedEntryOptions(available().filter(e=>e.type==='item'&&!e.magic&&C.referenceGroup(e)===group),'','Elegir al azar');}
function showRandomDraft(result){const e=result.entry;openEditor(result.sourceId,true);for(const [field,key]of [['name','name'],['description','description'],['attributes','attributes'],['price','price'],['rarity','rarity'],['craft','craftMode'],['days','days'],['materials','materials'],['components','componentsNote'],['bonus','enhancementBonus']])$('entry-'+field).value=e[key]??(field==='bonus'?0:'');for(const [field,key]of [['magic','magic'],['needs-base','needsBase'],['consumable','consumable'],['loot','loot']])$('entry-'+field).checked=!!e[key];savedMagicSpell=structuredClone(e.magicSpell||null);$('entry-magic-effect').value=e.magicEffect||'';$('magic-property-mode').value=e.magicSpell?(e.magicEffect?'both':'spell'):e.magicEffect?'ability':'none';$('magic-spell').innerHTML='';for(const key of ['activation','usage','uses','recovery'])if(e.magicSpell)$('magic-'+key).value=e.magicSpell[key];$('magic-spell-notes').value=e.magicSpell?.notes||'';updateEditor();toast('Borrador aleatorio: revisalo y guardá si te sirve.');}
function importPreview(packageData){pendingPackage=C.validatePackage(packageData);const collisions=pendingPackage.entries.filter(e=>db.entries.some(x=>x.id===e.id)).length;info('Importar contenido',`<p>${pendingPackage.entries.length} fichas · ${collisions} IDs coincidentes.</p><details class="fold"><summary>Contenido y procedencia</summary>${pendingPackage.entries.map(e=>`<p>${esc(e.name)} · ${esc(e.metadata?.author||'Autoría sin declarar')} · ${esc(e.metadata?.license||'Condiciones sin declarar')}</p>`).join('')}</details><form id="content-import-form">${scopeFields([db.campaign],'import')}<label>Si un ID ya existe<select id="collision-policy">${options([['skip','Omitir coincidentes'],['copy','Importar como copias con IDs nuevos']],'skip')}</select></label><p class="notice">No se reemplazan datos. Las fichas importadas quedan desactivadas hasta habilitarlas desde Contexto.</p><button class="primary full">Importar paquete</button></form>`);}
function newMerchant(){info('Comerciante',`<form id="merchant-form">${input('merchant-name','Nombre','','required maxlength="180"')}<label>Categorías que vende<select id="merchant-categories" multiple size="5">${options([...new Set(all().filter(e=>e.type==='item').map(e=>e.category))].map(c=>[c,c]),'Equipo')}</select></label>${scopeFields([db.campaign],'merchant')}<label>Notas<textarea id="merchant-note" maxlength="5000" rows="3"></textarea></label><p class="subtle">Las herramientas no limitan la creación. El DM decide qué ofrece. No se asignan capacidades especiales automáticamente.</p><button class="primary full">Guardar comerciante</button></form>`);}
function txtLoot(l){return[l.title,l.context,l.coins?'Monedas: '+displayCoins(l.coins):'',...(l.valuables||[]).map(e=>e.name+': '+pretty(e.price)),l.budget!=null?'Tesoro monetario: '+pretty(l.budget):'',...l.items.map(e=>e.name+' · '+pretty(e.price)+'\n'+e.description+'\n'+e.origin),...(l.warnings||[])].filter(Boolean).join('\n\n');}
function updateSettings(target){const key=target.dataset.setting;if(!key)return;if(target.type==='number'&&!target.checkValidity())return;db.settings[key]=target.type==='checkbox'?target.checked:['level','cr','count','ratio','magicPct','maxMagic','artifactPct'].includes(key)?Number(target.value):target.value;if(target.type==='range')target.closest('label').querySelector('output').textContent=target.value+(key==='ratio'?'×':'%');save();}
const foldState=new Map();
function foldKey(d){const identity=d.dataset.entry?'entry:'+d.dataset.entry:d.dataset.lootId?'loot:'+d.dataset.lootId:d.id||d.dataset.fold|| (d.classList.contains('context-line')?'loot-context':d.querySelector(':scope > summary')?.textContent.trim());const parent=d.parentElement.closest('details');return view+'|'+(parent?foldKey(parent)+'|':'')+identity;}
function rememberFolds(){document.querySelectorAll('details').forEach(d=>{const key=d.dataset.foldKey;if(key)foldState.set(key,d.open);});}
function restoreFolds(){document.querySelectorAll('details').forEach(d=>{const key=foldKey(d);d.dataset.foldKey=key;if(foldState.has(key))d.open=foldState.get(key);});}
function keepFolds(fn){return function(...args){rememberFolds();const result=fn(...args);restoreFolds();return result;};}
document.addEventListener('toggle',event=>{const d=event.target;if(d.matches?.('details')&&d.isConnected)foldState.set(d.dataset.foldKey||foldKey(d),d.open);},true);
document.addEventListener('input',event=>{const t=event.target;if(t.dataset.encSetting&&t.type==='number'){if(t.checkValidity()){try{updateEncounter(s=>s[t.dataset.encSetting]=Number(t.value));renderEncounterResult();}catch(err){toast(err.message);}}return;}if(t.id==='custom-list-name'&&listDraft)listDraft.name=t.value;if(t.id==='list-search'){listSearch=t.value;rightSelection.clear();renderTransferRows(true);}if(t.id==='entry-reference-search')filterReferences();if(t.id==='physical-d100')diceInputs.d100=t.value;if(t.id==='physical-d4')diceInputs.d4=t.value;if(t.id==='magic-spell-search')renderSpellOptions();if(t.id==='magic-uses')renderEditorCraft();if(['entry-price','entry-days','entry-materials'].includes(t.id))renderEditorCraft();if(t.id==='craft-sale'&&t.checkValidity()){craftSale=t.value===''?null:Number(t.value);const item=find(craftSelection),r=C.craft(item,db.merchants.find(m=>m.id===craftMaker)||null,craftQty,{extras:craftExtras,base:find(craftBase),makeBase,baseOwned,scrollLevel});$('craft-margin').textContent=pretty((craftSale??r.purchase)==null?null:(craftSale??r.purchase)-r.total);}if(t.id==='search'){query=t.value;page=0;renderList();}if(t.id==='loot-search')document.querySelectorAll('[data-loot-id]').forEach(d=>d.hidden=!C.norm(d.textContent).includes(C.norm(t.value)));if(t.dataset.setting)updateSettings(t);if(t.dataset.qty&&t.checkValidity()){shop().cart.find(l=>l.id===t.dataset.qty).qty=Number(t.value);save();const e=find(t.dataset.qty);document.querySelector(`[data-line-total="${t.dataset.qty}"]`).textContent=pretty(e.price==null?null:e.price*Number(t.value));$('cart-total').textContent=pretty(payable().amount);$('cart-fold').querySelector('summary').textContent='Compra · '+cartLines().length+' entradas · '+pretty(payable().amount)+(payable().pending?' + pendientes':'');changeOverride=null;renderPayment();}if(t.id==='discount'&&t.checkValidity()){shop().discount=Number(t.value);save();$('cart-total').textContent=pretty(payable().amount);$('cart-fold').querySelector('summary').textContent='Compra · '+cartLines().length+' entradas · '+pretty(payable().amount)+(payable().pending?' + pendientes':'');changeOverride=null;renderPayment();}if(t.dataset.pay){if(!t.checkValidity()){$('payment-result').innerHTML='<p class="notice">Ingresá cantidades enteras y no negativas de monedas.</p>';return;}shop().payment={...shop().payment,...Object.fromEntries(coinRegistry().map(([k])=>[k,Number($('pay-'+k).value||0)]))};save();changeOverride=null;renderPayment();}if(t.dataset.change){try{const coins=Object.fromEntries(coinRegistry().map(([k])=>[k,Number($('change-'+k).value||0)])),r=C.currencyPayment(payable().amount,shop().payment||{},db);changeOverride=coins;$('change-check').textContent=C.currencyValue(coins,coinRegistry())===C.currencyValue(r.change,coinRegistry())?'✓ Combinación exacta.':'La combinación no coincide: ajustá las monedas.';}catch(err){$('change-check').textContent=err.message;}}if(['craft-qty','craft-extras'].includes(t.id)&&t.checkValidity()){if(t.id==='craft-qty')craftQty=Number(t.value);else craftExtras=Number(t.value);renderCraftResult();}});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='monster-cr')$('monster-xp').value=C.xpForCR(t.value);if(t.dataset.encSetting){if(!t.checkValidity())return;try{const key=t.dataset.encSetting;updateEncounter(s=>s[key]=t.type==='checkbox'?t.checked:['level','players','maxCreatures'].includes(key)?Number(t.value):t.value);['pool','cr','creatureType'].includes(key)?renderEncounters():renderEncounterResult();}catch(err){toast(err.message);}return;}if(t.dataset.encQty||t.dataset.encLair){if(!t.checkValidity())return;try{updateEncounter(s=>{const row=s.rows.find(r=>r.id===(t.dataset.encQty||t.dataset.encLair));if(t.dataset.encQty)row.qty=Number(t.value);else row.lair=t.checked;});renderEncounterResult();}catch(err){toast(err.message);}return;}if(t.id==='monster-filter-cr'||t.id==='monster-filter-kind'){t.id==='monster-filter-cr'?monsterCR=t.value:monsterKind=t.value;page=0;renderList();}if(t.dataset.listPick){const set=t.dataset.listPick==='right'?rightSelection:leftSelection;t.checked?set.add(t.value):set.delete(t.value);updateTransferButtons();}if(t.id==='library-list'){libraryList=t.value;query='';filter='all';page=0;renderLibrary();}if(t.id==='custom-list-select'){captureListDraft();if(listDraft&&JSON.stringify(listDraft)!==JSON.stringify(db.customLists.find(l=>l.id===listDraft.id))&&(listDraft.name||listDraft.entryIds.length)&&!confirm('¿Cambiar de lista sin guardar estos cambios?')){t.value=db.customLists.some(l=>l.id===listDraft.id)?listDraft.id:'';return;}newListDraft(t.value);renderLibrary();}if(t.dataset.currencyOfficial||t.dataset.currencyEnable){const next=structuredClone(db),prefs=next.currencies[next.campaign];if(t.dataset.currencyOfficial)prefs[t.dataset.currencyOfficial]=t.checked;else prefs.custom.find(c=>c.key===t.dataset.currencyEnable).enabled=t.checked;try{C.validate(next);db=next;changeOverride=null;save();render();}catch(err){toast(err.message);t.checked=!t.checked;}}if(t.id==='entry-reference-group')filterReferences();if(t.id==='random-group')renderRandomBases();if(t.id==='draw-rarity')diceInputs.rarity=t.value;if(t.id==='draw-artifacts')diceInputs.artifacts=t.checked;if(t.id==='theme'){db.theme=t.value;save();document.body.dataset.theme=db.theme;}if(['campaign','context-selector'].includes(t.id)){db.campaign=t.value;encounterPreview=null;encounterLootSaved=false;merchantId='general';query='';page=0;activeId=null;changeOverride=null;save();render();}if(t.id==='filter'){filter=t.value;page=0;renderList();}if(t.id==='merchant'){merchantId=t.value;query='';filter='all';page=0;changeOverride=null;renderMarket();}if(t.id==='stock-mode'){shop().mode=t.value;save();renderList();}if(t.id==='stock-floor'&&t.checkValidity()){shop().floor=Number(t.value);save();}if(t.id==='electrum'){db.electrum=t.checked;changeOverride=null;save();renderPayment();}if(t.dataset.weight&&t.checkValidity()){db.settings.weights[Number(t.dataset.weight)]=Number(t.value);save();}if(t.dataset.setting){updateSettings(t);if(['autoWeights','level','kind'].includes(t.dataset.setting))renderLoot();}if(t.id==='craft-item'){craftSelection=t.value;craftSale=null;baseOwned=false;makeBase=false;const item=find(craftSelection),base=find(item?.parent);craftBase=item?.needsBase&&base&&!base.magic?base.id:'';renderCraft();}if(t.id==='craft-maker'){craftMaker=t.value;renderCraftResult();}if(t.id==='craft-base'){craftBase=t.value;renderCraftResult();}if(t.id==='base-mode'){baseOwned=t.value==='owned';makeBase=t.value==='make';renderCraftResult();}if(t.id==='scroll-level'){scrollLevel=Number(t.value);renderCraftResult();}if(t.id==='dice-family'||t.id==='dice-rarity'){db.dice[t.id==='dice-family'?'family':'rarity']=t.value;save();renderDice();}if(t.dataset.share){t.checked?selectedShare.add(t.dataset.share):selectedShare.delete(t.dataset.share);}if(t.dataset.lootEnable){find(t.dataset.lootEnable).loot=t.checked;save();}if(t.dataset.active){const next=structuredClone(db),disabled=new Set(next.disabled[next.campaign]||[]);t.checked?disabled.delete(t.dataset.active):disabled.add(t.dataset.active);next.disabled[next.campaign]=[...disabled];try{C.effective([...window.CATALOG_DATA,...next.entries],next.campaign,next.disabled);db=next;save();}catch(err){t.checked=!t.checked;toast(err.message);}}if(t.id.endsWith('-global')){const prefix=t.id.slice(0,-7);document.querySelectorAll(`[name="${prefix}-scope"]`).forEach(n=>n.disabled=t.checked);}if(t.id==='entry-type'){$('entry-reference-group').innerHTML=options([['all','Todos los tipos'],...[...new Set(referenceEntries(t.value).map(C.referenceGroup))].sort((a,b)=>a.localeCompare(b,'es')).map(x=>[x,x])],'all');$('entry-reference-search').value='';$('entry-parent').innerHTML=referenceOptions(t.value);$('entry-category').value=t.value==='item'?'Equipo':t.value==='service'?'Comida':'Otra';$('entry-category-other').value=C.TYPES[t.value];updateEditor();}if(['magic-property-mode','magic-usage'].includes(t.id)){updateMagicControls();renderEditorCraft();}if(['magic-spell','magic-activation','magic-recovery'].includes(t.id))renderEditorCraft();if(t.id==='entry-bonus')applyBonus();if(t.id==='entry-rarity'){$('entry-magic').checked=C.RARITIES.includes(t.value)||t.value==='Artefacto';if($('entry-magic').checked&&['none','common'].includes($('entry-craft').value))$('entry-craft').value='magic';}if(t.id==='entry-magic'){if(t.checked){if($('entry-rarity').value==='Mundano')$('entry-rarity').value='Común';if(['none','common'].includes($('entry-craft').value))$('entry-craft').value='magic';}else{$('entry-bonus').value='0';$('entry-rarity').value='Mundano';if($('entry-craft').value==='magic')$('entry-craft').value='common';}}if(['entry-category','entry-craft','entry-tool','entry-rarity','entry-magic','entry-consumable','entry-needs-base'].includes(t.id))updateEditor();if(t.id==='entry-parent'&&t.value){const base=find(t.value);$('entry-name').value=base.name;$('entry-description').value=base.description;$('entry-attributes').value=C.uniqueAttributes(base);$('entry-bonus').value=base.enhancementBonus||0;$('entry-components').value=base.componentsNote||'';$('entry-magic-effect').value=base.magicEffect||'';savedMagicSpell=structuredClone(base.magicSpell||null);$('magic-property-mode').value=base.magicSpell?(base.magicEffect?'both':'spell'):base.magicEffect?'ability':'none';$('magic-spell').innerHTML='';for(const key of ['activation','usage','uses','recovery'])$('magic-'+key).value=base.magicSpell?.[key]??({activation:'Según el conjuro',usage:'daily',uses:1,recovery:'Al amanecer'}[key]);$('magic-spell-notes').value=base.magicSpell?.notes||'';if(['item','service'].includes(base.type))$('entry-price').value=base.price??'';const category=$('entry-category');category.value=[...category.options].some(o=>o.value===base.category)?base.category:'Otra';$('entry-category-other').value=base.category||'';if(base.type==='item'){for(const [field,key] of [['rarity','rarity'],['craft','craftMode']])$('entry-'+field).value=base[key]||(field==='rarity'?'Mundano':'none');$('entry-tool').innerHTML=toolOptions(base.tool||'');for(const [field,key] of [['magic','magic'],['consumable','consumable'],['needs-base','needsBase'],['loot','loot']])$('entry-'+field).checked=!!base[key];$('entry-days').value=base.days??'';$('entry-materials').value=base.materials??'';}if(base.type==='service')$('entry-unit').value=base.unit||'';if(base.type==='monster')for(const key of ['cr','xp','lairXp','creatureType','ac','hp','speed']){const ids={cr:'monster-cr',xp:'monster-xp',lairXp:'monster-lair',creatureType:'monster-kind',ac:'monster-ac',hp:'monster-hp',speed:'monster-speed'};$(ids[key]).value=base.monster?.[key]??'';}if(base.type==='spell')for(const key of ['level','school','casting','range','components','duration'])$('spell-'+key).value=base.spell?.[key]??base[key]??(key==='level'?0:key==='school'?'Por definir':'');updateEditor();}});
$('editor-form').onsubmit=saveEntry;
document.addEventListener('submit',event=>{const id=event.target.id;if(id==='custom-list-form'){event.preventDefault();try{saveCustomList();}catch(err){toast(err.message);}}if(id==='list-import-form'){event.preventDefault();try{const r=C.mergeListPackage(db,pendingListPackage,getScope('list-import'),$('list-collision').value);db=r.db;pendingListPackage=null;save();$('info').close();libraryMode='custom';newListDraft(r.list.id);renderLibrary();toast('Lista importada.');}catch(err){toast(err.message);}}if(id==='currency-form'){event.preventDefault();try{const next=structuredClone(db),unit=C.BASE_COINS.find(c=>c[0]===$('currency-unit').value),value=Number($('currency-value').value)*unit[2];if(!Number.isSafeInteger(value)||value<1)throw Error('La equivalencia debe expresarse en unidades enteras de cobre.');next.currencies[next.campaign].custom.push({key:'local-'+C.uid(),name:$('currency-name').value.trim(),value,enabled:$('currency-enable-new').checked});C.validate(next);db=next;changeOverride=null;save();render();currencySettings();toast('Moneda agregada al contexto.');}catch(err){toast(err.message);}}if(id==='random-craft-form'){event.preventDefault();try{const draft=C.randomDraft(available(),{group:$('random-group').value,baseId:$('random-base').value,magic:$('random-magic').checked});$('info').close();showRandomDraft(draft);}catch(err){toast(err.message);}}if(id==='content-import-form'){event.preventDefault();try{const r=C.mergePackage(db,pendingPackage,getScope('import'),$('collision-policy').value);db=r.db;pendingPackage=null;save();$('info').close();render();toast(`${r.added} fichas agregadas; ${r.skipped} omitidas. Activación pendiente.`);}catch(err){toast(err.message);}}if(id==='merchant-form'){event.preventDefault();try{const name=$('merchant-name').value.trim(),categories=[...$('merchant-categories').selectedOptions].map(o=>o.value);if(!name||!categories.length)throw Error('Indicá nombre y al menos una categoría.');const m={id:'merchant-'+C.uid(),name,categories,scope:getScope('merchant'),note:$('merchant-note').value.trim(),tools:[],forge:false};db.merchants.push(m);merchantId=m.id;save();$('info').close();renderMarket();toast('Comerciante guardado.');}catch(err){toast(err.message);}}if(id==='context-form'){event.preventDefault();const name=$('context-name').value.trim();if(!name)return;const c={id:'context-'+C.uid(),name,description:'Contexto de contenido y reglas.'};db.campaigns.push(c);db.campaign=c.id;C.ensureCurrencies(db);save();$('info').close();render();}});
document.addEventListener('click',event=>{const b=event.target.closest('button');if(event.target.matches('[data-share]'))event.stopPropagation();if(!b)return;if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}if(b.dataset.view){navigate(b.dataset.view);return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;event.preventDefault();event.stopPropagation();try{
 if(action==='monster-xp'){$('monster-xp').value=C.xpForCR($('monster-cr').value);}
 if(action==='enc-generate'){const controls=[...document.querySelectorAll('[data-enc-setting]')];for(const control of controls)if(!control.reportValidity())return;updateEncounter(s=>controls.forEach(t=>s[t.dataset.encSetting]=t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value):t.value));const s=encounterState(),rows=C.generateEncounter(s,encounterPool());updateEncounter(s=>s.rows=rows);renderEncounterResult();}
 if(action==='enc-add'){const e=find($('enc-monster').value),qty=Number($('enc-add-qty').value);if(!e||!encounterPool().some(x=>x.id===e.id))throw Error('Elegí una criatura disponible.');addEncounterRow({id:e.id,qty,lair:false});}
 if(action==='enc-add-cr'){const cr=$('enc-manual-cr').value;addEncounterRow({id:'manual:'+C.uid(),cr,xp:C.xpForCR(cr),qty:Number($('enc-add-qty').value),lair:false});}
 if(action==='enc-new-monster'){openEditor();$('entry-type').value='monster';$('entry-reference-group').innerHTML=options([['all','Todos los tipos'],...[...new Set(referenceEntries('monster').map(C.referenceGroup))].map(g=>[g,g])],'all');$('entry-category').value='Otra';$('entry-category-other').value='Monstruos';$('entry-parent').innerHTML=referenceOptions('monster');updateEditor();}
 if(action==='enc-remove'){updateEncounter(s=>s.rows=s.rows.filter(r=>r.id!==id));renderEncounterResult();}
 if(action==='enc-clear'){updateEncounter(s=>s.rows=[]);renderEncounterResult();}
 if(action==='enc-export')download('encuentro.txt',encounterText(),'text/plain;charset=utf-8');
 if(action==='enc-loot'){encounterPreview=C.encounterLoot(encounterState(),available(),window.TABLE_DATA);encounterLootSaved=false;renderEncounterResult();}
 if(action==='enc-save-loot'&&encounterPreview&&!encounterLootSaved){const l={...structuredClone(encounterPreview),id:C.uid(),campaign:db.campaign,date:new Date().toISOString(),title:'Botín de encuentro',saved:false};const next=structuredClone(db);next.loot.unshift(l);db=C.validate(next);save();encounterLootSaved=true;renderEncounterResult();toast('Botín guardado en Loot.');}
 if(action==='library-mode'){captureListDraft();libraryMode=b.dataset.mode;query='';filter='all';page=0;renderLibrary();}
 if(action==='list-new'){captureListDraft();if(listDraft&&(listDraft.name||listDraft.entryIds.length)&&JSON.stringify(listDraft)!==JSON.stringify(db.customLists.find(l=>l.id===listDraft.id))&&!confirm('¿Empezar otra lista sin guardar estos cambios?'))return;newListDraft();renderLibrary();}
 if(action==='list-source'){captureListDraft();listSource=id;rightSelection.clear();listSearch='';renderListBuilder();}
 if(action==='list-add'||action==='list-remove'){captureListDraft();listDraft=C.updateList(listDraft,action==='list-add'?[...rightSelection].filter(id=>remainingSource().some(e=>e.id===id)):[...leftSelection],action==='list-remove');rightSelection.clear();leftSelection.clear();renderTransferRows();}
 if(action==='list-select-visible'){remainingSource().forEach(e=>rightSelection.add(e.id));renderTransferRows();}
 if(action==='list-entry-info'){const e=find(id);if(e)info(e.name,entryBody(e));}
 if(action==='list-export'){captureListDraft();download('botin-lista.json',JSON.stringify(C.packageList(listDraft,all()),null,2));}
 if(action==='list-import')$('list-file').click();
 if(action==='prev'||action==='next'){page+=action==='prev'?-1:1;renderList();}
 if(action==='view-base'){const base=find(id);if(base)info('Referencia de origen · '+base.name,`<div class="description sheet">${sheet(base)}</div><p class="source">${esc(base.origin)} · ${esc(pretty(base.price))}</p><p class="subtle">Referencia conservada para consultar procedencia y propiedades. No reemplaza la descripción del objeto propio.</p>`);}if(action==='magic-price'){if(Number($('entry-bonus').value)>4)throw Error('+5 queda fuera de la guía: el precio lo define el DM.');const base=find($('entry-parent').value),price=C.magicValue($('entry-rarity').value,$('entry-consumable').checked,$('entry-needs-base').checked?(base&&!base.magic?base.price:null):0);if(!$('entry-magic').checked||$('entry-craft').value==='scroll'||price==null)throw Error('Elegí una rareza mágica y, si corresponde, una referencia base no mágica. Los pergaminos usan su nivel.');$('entry-price').value=price;renderEditorCraft();}if(action==='currencies')currencySettings();if(action==='random-craft')randomCreator();if(action==='new-craft'){openEditor();$('entry-craft').value='common';updateEditor();}if(action==='imbue-entry')prepareImbuing(id);if(action==='new-entry')openEditor();if(action==='edit-entry'||action==='clone-entry')openEditor(id,action==='clone-entry');
 if(action==='craft-entry'){craftSelection=id;craftMaker='';navigate('craft');}
 if(action==='new-merchant')newMerchant();if(action==='market-kind'){marketKind=b.dataset.kind;filter='all';query='';page=0;renderMarket();}
 if(action==='cart-add'){if(!saleItems().some(e=>e.id===id))return;const line=shop().cart.find(l=>l.id===id);if(line){if(line.qty>=10000)throw Error('Cantidad máxima: 10000.');line.qty++;}else shop().cart.push({id,qty:1});changeOverride=null;save();renderCart();toast('Agregado a la compra.');}
 if(action==='cart-remove'){shop().cart=shop().cart.filter(l=>l.id!==id);changeOverride=null;save();renderCart();}
 if(action==='cart-clear'&&confirm('¿Vaciar esta compra?')){shop().cart=[];changeOverride=null;save();renderCart();}
 if(action==='cart-export')download('compra.txt',cartLines().map(l=>`${l.qty} × ${find(l.id).name} · ${pretty(find(l.id).price==null?null:find(l.id).price*l.qty)}`).join('\n')+'\n\n'+(payable().pending?'Subtotal conocido: ':'Total: ')+pretty(payable().amount),'text/plain;charset=utf-8');
 if(action==='restock'){shop().stock=C.stock(saleItems().filter(e=>e.type==='item'),shop().floor);shop().mode='random';save();renderMarket();toast('Stock renovado.');}
 if(action==='generate-quick'||action==='generate-manual'){C.validate(db);const mode=action==='generate-quick'?'quick':'manual';if(mode==='manual'&&db.settings.artifacts&&!available().some(e=>e.loot&&e.rarity==='Artefacto'))throw Error('Creá y habilitá un artefacto propio o desactivá esa excepción.');const result=C.generate(db.settings,available(),window.TABLE_DATA,mode);storeResult(result,mode==='manual'&&db.settings.title?db.settings.title:`${mode==='quick'?db.settings.kind:db.settings.source} · ${mode==='quick'?'DMG':'manual'}`);}
 if(action==='random-name'){db.settings.title=C.sample(['Cofre','Alijo','Hallazgo','Botín'])+' '+C.sample(['del camino','de la torre','de la guardia','olvidado']);$('loot-title').value=db.settings.title;save();}
 if(action==='reset-loot'&&confirm('¿Restablecer la configuración de loot?')){db.settings=C.settings();save();renderLoot();}
 if(action==='save-list'){const l=db.loot.find(l=>l.id===id);l.saved=!l.saved;save();view==='loot'?renderLoot():renderDice();}
 if(action==='loot-txt')download('loot-'+id+'.txt',txtLoot(db.loot.find(l=>l.id===id)),'text/plain;charset=utf-8');
 if(action==='delete-loot'&&confirm('¿Eliminar este resultado?')){db.loot=db.loot.filter(l=>l.id!==id);save();render();}
 if(action==='clean-screen'){db.hiddenLoot=[...new Set([...db.hiddenLoot,...db.loot.filter(l=>l.campaign===db.campaign).map(l=>l.id)])];save();renderLoot();}
 if(action==='show-history'){db.hiddenLoot=db.hiddenLoot.filter(id=>!db.loot.some(l=>l.id===id&&l.campaign===db.campaign));save();renderLoot();}
 if(action==='clean-history'&&confirm('¿Eliminar resultados no marcados como listas guardadas de este contexto?')){db.loot=db.loot.filter(l=>l.campaign!==db.campaign||l.saved);db.hiddenLoot=db.hiddenLoot.filter(id=>db.loot.some(l=>l.id===id));save();renderLoot();}
 if(action==='dice-roll')resolveDice(C.roll(1,100));if(action==='dice-physical'){const raw=$('physical-d100').value.trim();if(!raw)throw Error('Ingresá el resultado del dado.');resolveDice(raw==='00'?100:Number(raw),true);}
 if(action==='equipment-renew'&&confirm('¿Regenerar solo posiciones 83–100?')){db.equipmentTable=C.equipmentTable(window.TABLE_DATA);save();renderDice();}
 if(action==='catalog-draw'){const rarity=$('draw-rarity').value,artifacts=$('draw-artifacts').checked,pool=available().filter(e=>e.type==='item'&&e.loot&&e.magic&&(artifacts||e.rarity!=='Artefacto')&&(rarity==='all'||e.rarity===rarity));if(!pool.length)throw Error('No hay objetos elegibles para esos filtros.');const e=C.sample(pool);storeResult({items:[C.snapshot(e)],mode:'Sorteo',context:'Sorteo uniforme · filtros independientes de Loot',warnings:[]},'Sorteo · '+e.name);}
 if(action==='new-context')info('Contexto de reglas',`<form id="context-form">${input('context-name','Nombre','','required maxlength="180"')}<p class="subtle">Solo selecciona contenido y reglas; no registra sesiones ni tramas.</p><button class="primary full">Crear contexto</button></form>`);
 if(action==='confirm-restore'&&pendingBackup){db=pendingBackup;pendingBackup=null;listDraft=null;pendingListPackage=null;encounterPreview=null;encounterLootSaved=false;blocked=false;selectedShare.clear();merchantId='general';latest=null;changeOverride=null;save();$('info').close();render();toast('Respaldo restaurado.');}if(action==='export-backup')download('botin-respaldo-v2.json',JSON.stringify(db,null,2));if(action==='restore-backup')$('backup-file').click();if(action==='import-content')$('content-file').click();
 if(action==='export-content'||action==='export-all-own'){const entries=db.entries.filter(e=>action==='export-all-own'||selectedShare.has(e.id));if(!entries.length)throw Error('Seleccioná contenido propio para compartir. Las fichas base permanecen en la biblioteca.');download('botin-contenido.json',JSON.stringify(C.packageContent(entries),null,2));}
}catch(err){toast(err.message);}});
async function readFile(input){const f=input.files[0];input.value='';if(!f)return null;if(f.size>15000000)throw Error('El archivo supera 15 MB.');return JSON.parse(await f.text());}
$('list-file').onchange=async event=>{try{const raw=await readFile(event.target);if(raw)listImportPreview(raw);}catch(err){toast('No se importó: '+err.message);}};
$('backup-file').onchange=async event=>{try{const raw=await readFile(event.target);if(!raw)return;pendingBackup=C.validate(raw);info('Restaurar respaldo completo',`<p>Reemplaza el estado completo de este prototipo por el archivo elegido. Exportá antes lo que quieras conservar.</p><p>${pendingBackup.entries.length} fichas propias · ${pendingBackup.loot.length} resultados · ${pendingBackup.campaigns.length} contextos.</p><button class="primary" data-action="confirm-restore">Restaurar este respaldo</button>`);}catch(err){pendingBackup=null;toast('No se restauró: '+err.message);}};
$('content-file').onchange=async event=>{try{const raw=await readFile(event.target);if(raw)importPreview(raw);}catch(err){toast('No se importó: '+err.message);}};
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
if(blocked){$('save-status').textContent='⚠';$('save-status').title='Datos previos protegidos; no se sobrescriben.';toast('No se pudieron leer los datos guardados. Exportá la sesión o restaurá un respaldo válido.');}
openEditor=keepFolds(openEditor);info=keepFolds(info);render=keepFolds(render);renderLoot=keepFolds(renderLoot);renderDice=keepFolds(renderDice);renderLibrary=keepFolds(renderLibrary);renderListBuilder=keepFolds(renderListBuilder);renderList=keepFolds(renderList);renderMarket=keepFolds(renderMarket);renderCart=keepFolds(renderCart);renderPayment=keepFolds(renderPayment);renderCraft=keepFolds(renderCraft);renderCraftResult=keepFolds(renderCraftResult);renderEncounters=keepFolds(renderEncounters);renderEncounterResult=keepFolds(renderEncounterResult);
const hash=location.hash.slice(1);navigate(hash||'loot');if(!blocked)save();
})();
